INSERT INTO categories (id, name, description) VALUES ('mba-entrance', 'MBA Entrance (CAT/XAT/MAT)', 'Quantitative aptitude, verbal ability, logical reasoning, and data interpretation for MBA entrance exams.');

INSERT INTO question_sets (id, owner_user_id, title, track, visibility, created_at, approved_at, approved_by) VALUES ('mba-entrance-bank', NULL, 'MBA Entrance Prep', 'mba', 'shared', '2026-11-14T06:17:56.365Z', '2026-11-14T06:17:56.365Z', NULL);
INSERT INTO question_set_categories (set_id, category_id) VALUES ('mba-entrance-bank', 'mba-entrance');

INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00001', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 0, 'Find the remainder when 7^100 is divided by 100.', 'Look at the cycle of `7^n mod 100`: `7^1=7`, `7^2=49`, `7^3=343 → 43`, `7^4=2401 → 1`.

Since `7^4 ≡ 1 (mod 100)` and `100 = 4 × 25`, we get `7^100 = (7^4)^25 ≡ 1^25 = 1 (mod 100)`.

The remainder is **1**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00002', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 1, 'How many trailing zeros are there in 100! (100 factorial)?', 'Trailing zeros come from factors of **10 = 2 × 5**, and factors of 2 are far more abundant than factors of 5 in `100!`, so we only need to count powers of 5.

`floor(100/5) + floor(100/25) + floor(100/125) = 20 + 4 + 0 = 24`.

`100!` ends in **24 zeros**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00003', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 2, 'A number N, when divided by 13, leaves a remainder of 7. What is the remainder when N² is divided by 13?', 'If `N ≡ 7 (mod 13)`, then `N² ≡ 7² = 49 (mod 13)`.

`49 = 3×13 + 10`, so `49 ≡ 10 (mod 13)`.

The remainder is **10**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00004', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 3, 'Find the sum of all 3-digit numbers divisible by 7.', 'The smallest 3-digit multiple of 7 is **105** (`= 15 × 7`) and the largest is **994** (`= 142 × 7`).

Number of terms: `142 - 15 + 1 = 128`.

Using `Sum = n/2 × (first + last) = 128/2 × (105 + 994) = 64 × 1099 = 70336`.

The required sum is **70,336**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00005', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 4, 'The HCF and LCM of two numbers are 12 and 336 respectively. If one of the numbers is 48, find the other.', 'For any two numbers, `Product of numbers = HCF × LCM`.

So `48 × Other = 12 × 336 = 4032`, which gives `Other = 4032 / 48 = 84`.

The other number is **84**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00006', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 5, 'Find the smallest number which, when divided by 6, 9, 15 and 18, leaves a remainder of 4 in each case.', 'Since the remainder is the same (4) in every case, the required number is of the form `LCM(6, 9, 15, 18) + 4`.

`LCM(6, 9, 15, 18) = 90`.

So the smallest such number is `90 + 4 = **94**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00007', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 6, 'How many numbers from 1 to 1000 (inclusive) are divisible by neither 3 nor 5?', 'Multiples of 3: `floor(1000/3) = 333`. Multiples of 5: `floor(1000/5) = 200`. Multiples of 15 (both): `floor(1000/15) = 66`.

By the inclusion-exclusion principle, numbers divisible by 3 or 5 = `333 + 200 - 66 = 467`.

Numbers divisible by neither = `1000 - 467 = **533**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00008', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 7, 'Find the unit digit of 17^23 × 13^22.', 'The unit digit of powers of 17 follows the cycle of 7: `7, 9, 3, 1` repeating every 4 powers. Since `23 mod 4 = 3`, the unit digit of `17^23` is the 3rd term, **3**.

The unit digit of powers of 13 follows the cycle of 3: `3, 9, 7, 1` repeating every 4 powers. Since `22 mod 4 = 2`, the unit digit of `13^22` is the 2nd term, **9**.

Multiplying the unit digits: `3 × 9 = 27`, so the final unit digit is **7**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00009', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 8, 'In an election between two candidates, the winner secured 60% of the votes polled and won by a margin of 4800 votes. Assuming no invalid votes, find the total number of votes polled.', 'Winner''s share = **60%**, loser''s share = **40%**, so the margin represents `60% - 40% = 20%` of total votes.

`20% of Total = 4800`, so `Total = 4800 / 0.20 = **24,000** votes`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00010', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 9, 'The price of an item is increased by 25% and then decreased by 20%. What is the net percentage change in price?', 'A successive change of `+25%` and `-20%` multiplies the price by `1.25 × 0.80 = 1.00`.

Since the net multiplying factor is exactly 1, there is **no net change** in price (0%).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00011', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 10, 'A''s salary is 25% more than B''s salary. By what percentage is B''s salary less than A''s?', 'Let B''s salary = **100**, so A''s salary = **125**.

B is less than A by `(125 - 100)/125 × 100 = 2500/125 = **20%**`.

Note the asymmetry: A is 25% more than B, but B is only 20% less than A — the base of comparison changes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00012', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 11, 'In a class, 40% of the students are girls and the rest are boys. If 70% of the girls and 60% of the boys passed an exam, find the overall pass percentage of the class.', 'Assume total strength = **100** students: girls = 40, boys = 60.

Girls who passed = `70% of 40 = 28`. Boys who passed = `60% of 60 = 36`.

Total passed = `28 + 36 = 64`, so the overall pass percentage is **64%**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00013', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 12, 'If the numerator of a fraction is increased by 20% and the denominator is decreased by 10%, the fraction becomes 4/5. Find the original fraction.', 'Let the original fraction be `x/y`. The condition gives `(1.2x)/(0.9y) = 4/5`.

This simplifies to `(x/y) × (1.2/0.9) = 4/5`, i.e., `(x/y) × (4/3) = 4/5`.

Solving, `x/y = (4/5) × (3/4) = **3/5**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00014', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 13, 'A number was to be divided by 3/5 but was mistakenly multiplied by 3/5 instead. Find the percentage error in the result.', 'Correct result `= N ÷ (3/5) = 5N/3`. Wrong result `= N × (3/5) = 3N/5`.

Error = `5N/3 - 3N/5 = (25N - 9N)/15 = 16N/15`.

Percentage error `= (16N/15) ÷ (5N/3) × 100 = (16/15) × (3/5) × 100 = **64%**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00015', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 14, 'A shopkeeper marks his goods 40% above the cost price and then allows a discount of 15%. Find his profit percentage.', 'Let cost price (CP) = **100**. Marked price = `140`.

Selling price after 15% discount = `140 × 0.85 = 119`.

Profit percentage = `119 - 100 = **19%**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00016', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 15, 'By selling an article for Rs. 450, a man loses 10%. At what price should he sell it to gain 10%?', 'Since `450` represents a 10% loss, `CP × 0.9 = 450`, so `CP = 450/0.9 = **Rs. 500**`.

To gain 10%, selling price should be `500 × 1.1 = **Rs. 550**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00017', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 16, 'A trader professes to sell goods at a profit of 20% over cost price, but he uses a weight of 800 g instead of 1 kg while buying and selling at the 1 kg price. Find his actual profit percentage.', 'Let the cost of 1000 g = **Rs. 100**, so cost per gram = Rs. 0.10.

He sells only **800 g** but charges the price meant for 1 kg marked up by 20%, i.e., he charges `100 × 1.2 = Rs. 120`.

His actual cost for 800 g = `80 × 1 = Rs. 80`. Profit = `120 - 80 = 40` on a cost of 80, giving a profit percentage of `40/80 × 100 = **50%**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00018', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 17, 'Two articles are sold at the same selling price — one at a profit of 20% and the other at a loss of 20%. Find the overall profit or loss percentage on the whole transaction.', 'Whenever two items are sold at the **same selling price** with equal percentage profit `x%` on one and equal percentage loss `x%` on the other, there is always a net **loss**, given by `loss% = (x/10)² = x²/100`.

Here `x = 20`, so `loss% = 20²/100 = 400/100 = **4%** loss`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00019', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 18, 'A dishonest dealer professes to sell his goods at cost price but uses a false weight and gains 25%. What weight does he actually give to a customer asking for 1000 g?', 'If the dealer gains 25% while charging the cost-price rate, the weight he actually hands over must satisfy `1000 g = (1 + 25/100) × (actual weight given)`.

So actual weight = `1000 / 1.25 = **800 g**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00020', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 19, 'The cost price of 20 articles is equal to the selling price of 16 articles. Find the profit percentage.', 'Let cost price of 1 article = **C**. Then `20C = 16 × SP`, so `SP = 20C/16 = 1.25C`.

Profit percentage = `(SP - C)/C × 100 = 0.25C/C × 100 = **25%**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00021', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 20, 'Find the compound interest on Rs. 20,000 at 10% per annum for 2 years, compounded annually.', 'Amount `A = P(1 + r/100)^n = 20000 × (1.1)^2 = 20000 × 1.21 = Rs. 24,200`.

Compound Interest = `A - P = 24200 - 20000 = **Rs. 4,200**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00022', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 21, 'The difference between compound interest and simple interest on a certain sum for 2 years at 10% per annum is Rs. 150. Find the sum.', 'For 2 years, the well-known identity is `CI - SI = P × (r/100)²`.

Here, `P × (10/100)² = 150`, i.e., `P × 0.01 = 150`.

Solving, `P = **Rs. 15,000**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00023', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 22, 'A sum of money doubles itself in 8 years at simple interest. Find the rate of interest per annum.', 'If the sum doubles, the **Simple Interest equals the Principal** itself over 8 years.

Using `SI = P × R × T / 100`, we get `P = P × R × 8 / 100`.

Solving, `R = 100/8 = **12.5%** per annum`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00024', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 23, 'Find the time in which a sum of money becomes 4 times itself at 15% per annum simple interest.', 'If the amount becomes 4 times the principal, the Simple Interest generated equals `3P` (since `Amount = P + SI = 4P`).

Using `SI = P × R × T/100`: `3P = P × 15 × T / 100`.

Solving, `T = 300/15 = **20 years**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00025', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 24, 'At what rate of compound interest per annum will Rs. 1000 become Rs. 1331 in 3 years, interest being compounded annually?', '`1331/1000 = 1.331`, and we need `(1 + r/100)^3 = 1.331`.

Since `1.1^3 = 1.331`, we get `1 + r/100 = 1.1`.

So the rate is **10%** per annum.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00026', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 25, 'A sum invested at compound interest amounts to Rs. 2420 at the end of 2 years and Rs. 2662 at the end of 3 years. Find the rate of interest per annum.', 'The interest earned in the 3rd year alone is `2662 - 2420 = Rs. 242`, and this is `r%` of the amount at the end of year 2 (Rs. 2420).

So `242/2420 × 100 = **10%** per annum`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00027', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 26, 'The average weight of 30 students in a class is 45 kg. When the class teacher is also included, the average weight increases by 1 kg. Find the weight of the teacher.', 'Total weight of 30 students = `30 × 45 = 1350 kg`.

With the teacher included, there are 31 people with a new average of `45 + 1 = 46 kg`, so the new total = `31 × 46 = 1426 kg`.

Teacher''s weight = `1426 - 1350 = **76 kg**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00028', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 27, 'The average of 11 numbers is 42. The average of the first six numbers is 37 and that of the last six numbers is 46. Find the sixth number.', 'Sum of all 11 numbers = `11 × 42 = 462`.

Sum of first six = `6 × 37 = 222`; sum of last six = `6 × 46 = 276`. Adding these counts the 6th number **twice**: `222 + 276 = 498`.

So the 6th number = `498 - 462 = **36**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00029', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 28, 'A mixture of 40 litres contains milk and water in the ratio 3:1. How much water must be added to make the ratio of milk to water 2:1?', 'In 40 litres with ratio `3:1`, milk = `30 L` and water = `10 L`.

For the new ratio `milk : water = 2:1`, water required `= milk/2 = 30/2 = 15 L`.

Water to be added = `15 - 10 = **5 litres**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00030', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 29, 'In what ratio must a 20% alcohol solution be mixed with a 50% alcohol solution to obtain a 30% alcohol solution?', 'Using the rule of alligation, the ratio of quantities is `(dearer - mean) : (mean - cheaper) = (50 - 30) : (30 - 20) = 20 : 10 = 2:1`.

This ratio applies to the **cheaper (20%) to dearer (50%)** quantities respectively.

So the 20% solution and the 50% solution must be mixed in the ratio **2 : 1**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00031', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 30, 'The average age of a family of 5 members is 25 years. If the age of the youngest member is 10 years, find the average age of the family at the time of birth of the youngest member.', 'Present total age of all 5 members = `5 × 25 = 125 years`. Excluding the youngest (10 years), the other 4 members'' present total age = `125 - 10 = 115 years`.

Ten years ago (at the birth of the youngest), those same 4 members'' total age was `115 - 4×10 = 75 years`, and the youngest wasn''t born yet, so the family had only 4 members.

Average age then = `75/4 = **18.75 years**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00032', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 31, 'A vessel contains a mixture of acid and water in the ratio 5:3. If 16 litres of the mixture is removed and replaced with water, the new ratio of acid to water becomes 5:7. Find the initial quantity of mixture in the vessel.', 'Let the total volume be `V` litres. Initially, acid forms `5/8` of the mixture.

After removing and replacing `16 L` with water, the fraction of acid remaining is `(5/8) × (1 - 16/V)`. This must equal the new acid fraction `5/12` (since the new ratio 5:7 has acid as 5 parts out of 12).

So `(5/8)(1 - 16/V) = 5/12`, giving `1 - 16/V = 8/12 = 2/3`, i.e., `16/V = 1/3`, so `V = **48 litres**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00033', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 32, 'A can complete a piece of work in 12 days and B in 18 days. They work together for 4 days, after which A leaves. In how many more days will B finish the remaining work alone?', 'A''s rate = `1/12` work/day; B''s rate = `1/18` work/day. Combined rate = `1/12 + 1/18 = 3/36 + 2/36 = 5/36` work/day.

In 4 days together, they complete `4 × 5/36 = 20/36 = 5/9` of the work, leaving `4/9` remaining.

B alone, at rate `1/18`, takes `(4/9) ÷ (1/18) = (4/9) × 18 = **8 days**` to finish the rest.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00034', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 33, 'A and B together can complete a work in 10 days. B and C together can complete it in 15 days. C and A together can complete it in 12 days. In how many days can A alone complete the work?', 'Let `1/A, 1/B, 1/C` be the daily work rates. We have `1/A + 1/B = 1/10`, `1/B + 1/C = 1/15`, `1/C + 1/A = 1/12`.

Adding all three: `2(1/A + 1/B + 1/C) = 1/10 + 1/15 + 1/12`. Taking LCM 60: `6/60 + 4/60 + 5/60 = 15/60 = 1/4`, so `1/A + 1/B + 1/C = 1/8`.

Subtracting `(1/B + 1/C) = 1/15` from this: `1/A = 1/8 - 1/15 = (15 - 8)/120 = 7/120`, so A alone takes `120/7 ≈ **17.14 days**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00035', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 34, '12 men can complete a work in 18 days. After working for 6 days, 4 more men join them. In how many additional days will the remaining work be completed?', 'Total work = `12 men × 18 days = 216 man-days`.

Work done in the first 6 days by 12 men = `12 × 6 = 72 man-days`, leaving `216 - 72 = 144 man-days` of work.

With `12 + 4 = 16` men now working, the remaining time = `144/16 = **9 more days**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00036', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 35, 'A is thrice as efficient as B and therefore takes 20 days less than B to complete a job. In how many days can A and B together complete the job?', 'If A is thrice as efficient as B, A takes **one-third** the time B takes. Let B''s time = `x` days, so A''s time = `x/3` days.

Given `x - x/3 = 20`, i.e., `2x/3 = 20`, so `x = 30`. Thus B takes 30 days and A takes **10 days**.

Combined rate = `1/10 + 1/30 = 3/30 + 1/30 = 4/30 = 2/15`, so together they take `15/2 = **7.5 days**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00037', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 36, 'A pipe can fill a tank in 6 hours. Due to a leak in the bottom, it takes 8 hours to fill the tank. How long would the leak alone take to empty the full tank?', 'Pipe''s filling rate = `1/6` tank/hour. With the leak, the net rate = `1/8` tank/hour.

Leak''s emptying rate = `1/6 - 1/8 = 4/24 - 3/24 = 1/24` tank/hour.

So the leak alone would empty the full tank in **24 hours**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00038', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 37, '3 men and 4 women can complete a work in 10 days, while 4 men and 6 women can complete the same work in 7 days. Find the number of days in which 1 man alone can complete the work.', 'Let a man''s daily work rate be `m` and a woman''s be `w`. From the given data: `10(3m + 4w) = 1` and `7(4m + 6w) = 1`, i.e., `3m + 4w = 1/10` and `4m + 6w = 1/7`.

Multiply the first equation by 3 and the second by 2: `9m + 12w = 3/10` and `8m + 12w = 2/7`.

Subtracting: `m = 3/10 - 2/7 = (21 - 20)/70 = 1/70`. So one man alone takes **70 days** to complete the work.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00039', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 38, 'A train 150 m long crosses a platform 250 m long in 20 seconds. Find the speed of the train in km/hr.', 'To cross the platform, the train must cover its own length plus the platform''s length: `150 + 250 = 400 m`.

Speed = `400 m / 20 s = 20 m/s`.

Converting to km/hr: `20 × 18/5 = **72 km/hr**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00040', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 39, 'Two trains of length 120 m and 180 m run on parallel tracks in opposite directions at speeds 54 km/hr and 36 km/hr respectively. Find the time taken for them to cross each other.', 'Since the trains move in **opposite directions**, relative speed = `54 + 36 = 90 km/hr = 90 × 5/18 = 25 m/s`.

Total distance to be covered (sum of lengths) = `120 + 180 = 300 m`.

Time taken = `300/25 = **12 seconds**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00041', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 40, 'A boat''s speed in still water is 10 km/hr and the speed of the stream is 2 km/hr. Find the total time taken by the boat to travel 24 km downstream and then return to the starting point.', 'Downstream speed = `10 + 2 = 12 km/hr`, so time downstream = `24/12 = 2 hours`.

Upstream speed = `10 - 2 = 8 km/hr`, so time upstream = `24/8 = 3 hours`.

Total time = `2 + 3 = **5 hours**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00042', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 41, 'A car covers a certain distance at a speed of 60 km/hr and returns over the same distance at a speed of 40 km/hr. Find the average speed for the entire journey.', 'When equal distances are covered at two different speeds `a` and `b`, the average speed is the **harmonic mean**: `2ab/(a+b)`, not the simple average.

Here, average speed = `2 × 60 × 40 / (60 + 40) = 4800/100 = **48 km/hr**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00043', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 42, 'Two stations A and B are 300 km apart. A train starts from A towards B at 9:00 am at 60 km/hr, and at the same time another train starts from B towards A at 40 km/hr. At what time will they meet?', 'Since the trains move towards each other, relative speed = `60 + 40 = 100 km/hr`.

Time to meet = `Distance / Relative speed = 300/100 = 3 hours`.

Starting at 9:00 am, they meet after 3 hours, i.e., at **12:00 noon**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00044', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 43, 'A man walking at 3/4th of his usual speed reaches his office 20 minutes late. Find his usual time to reach the office.', 'Speed and time are inversely proportional, so if speed becomes `3/4` of usual, time becomes `4/3` of usual.

Extra time taken = `(4/3 - 1) × usual time = (1/3) × usual time`, and this equals 20 minutes.

So usual time = `20 × 3 = **60 minutes**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00045', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 44, 'A thief is spotted by a policeman from a distance of 100 m. When the policeman starts the chase, the thief also starts running. If the thief''s speed is 10 km/hr and the policeman''s speed is 12 km/hr, find the distance the thief runs before being caught.', 'The policeman closes the gap at the **relative speed** of `12 - 10 = 2 km/hr`, needing to cover `100 m = 0.1 km`.

Time taken to catch the thief = `0.1/2 = 0.05 hours`.

Distance run by the thief in that time = `10 × 0.05 = **0.5 km = 500 m**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00046', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 45, 'A, B and C start at the same time, in the same direction, to run around a circular track of length 1200 m. A completes one round in 250 seconds, B in 300 seconds, and C in 360 seconds. After how much time will all three meet again at the starting point?', 'All three meet at the starting point simultaneously after a time equal to the **LCM of their individual lap times**.

`250 = 2 × 5³`, `300 = 2² × 3 × 5²`, `360 = 2³ × 3² × 5`. So `LCM = 2³ × 3² × 5³ = 8 × 9 × 125 = 9000` seconds.

`9000 seconds = **2.5 hours**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00047', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 46, 'Solve for x: 2x² - 7x + 3 = 0.', 'Using the quadratic formula with `a = 2, b = -7, c = 3`: discriminant `= b² - 4ac = 49 - 24 = 25`.

`x = (7 ± √25) / 4 = (7 ± 5)/4`.

This gives `x = 3` or `x = **1/2**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00048', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 47, 'If x + 1/x = 5, find the value of x² + 1/x².', 'Squaring both sides of `x + 1/x = 5` gives `x² + 2(x)(1/x) + 1/x² = 25`, i.e., `x² + 1/x² + 2 = 25`.

So `x² + 1/x² = 25 - 2 = **23**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00049', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 48, 'Find the number of integer solutions of the inequality x² - 5x + 6 ≤ 0.', 'Factorising: `x² - 5x + 6 = (x - 2)(x - 3)`. The inequality `(x-2)(x-3) ≤ 0` holds when **x lies between the roots**, inclusive, since the parabola opens upward.

So `2 ≤ x ≤ 3`.

The integers satisfying this are `x = 2` and `x = 3`, giving exactly **2 integer solutions**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00050', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 49, 'If f(x) = 2x + 3 and g(x) = x² - 1, find the value of f(g(2)).', 'First evaluate the inner function: `g(2) = 2² - 1 = 4 - 1 = 3`.

Now apply `f` to this result: `f(3) = 2(3) + 3 = 6 + 3 = **9**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00051', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 50, 'The sum of three consecutive even numbers is 54. Find the largest of these numbers.', 'Let the three consecutive even numbers be `n-2, n, n+2`.

Their sum is `3n = 54`, so `n = 18`.

The largest number is `n + 2 = **20**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00052', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 51, 'Solve the inequality 3x - 7 > 2x + 5 and find the range of x.', 'Bringing the x-terms to one side and constants to the other: `3x - 2x > 5 + 7`.

This simplifies to `x > **12**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00053', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 52, 'If a and b are the roots of x² - 6x + 8 = 0, find the value of a² + b².', 'From the equation, the sum of roots `a + b = 6` and the product `ab = 8` (by Vieta''s formulas).

Using the identity `a² + b² = (a+b)² - 2ab`: `a² + b² = 6² - 2(8) = 36 - 16 = **20**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00054', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 53, 'A two-digit number has digits whose sum is 9. If 27 is subtracted from the number, the digits interchange their positions. Find the number.', 'Let the tens digit be `a` and the units digit be `b`, so `a + b = 9` and the number is `10a + b`.

Subtracting 27 reverses the digits: `10a + b - 27 = 10b + a`, which simplifies to `9a - 9b = 27`, i.e., `a - b = 3`.

Solving `a + b = 9` and `a - b = 3` together gives `a = 6, b = 3`. The number is **63**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00055', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 54, 'Find the value of log base 2 of 64, i.e., log₂ 64.', 'We need the power to which 2 must be raised to get 64.

Since `2^6 = 64`, we have `log₂ 64 = **6**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00056', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 55, 'Given log 2 = 0.301 and log 3 = 0.477, find the value of log 6.', 'Since `6 = 2 × 3`, by the product rule of logarithms, `log 6 = log 2 + log 3`.

`log 6 = 0.301 + 0.477 = **0.778**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00057', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 56, 'Find the sum of the first 20 terms of the arithmetic progression 3, 7, 11, 15, ...', 'Here the first term `a = 3` and common difference `d = 4`, with `n = 20` terms.

Using `Sum = (n/2) × [2a + (n-1)d] = (20/2) × [2(3) + 19(4)] = 10 × [6 + 76] = 10 × 82`.

The sum is **820**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00058', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 57, 'The 5th term of a geometric progression is 48 and the 8th term is 384. Find the common ratio.', 'Let the first term be `a` and common ratio `r`. Then `ar⁴ = 48` and `ar⁷ = 384`.

Dividing the second by the first: `r³ = 384/48 = 8`.

So `r = **2**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00059', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 58, 'Find the sum to infinity of the geometric progression 8, 4, 2, 1, ...', 'Here, first term `a = 8` and common ratio `r = 1/2` (since `|r| < 1`, the infinite sum converges).

Using `Sum to infinity = a/(1-r) = 8/(1 - 0.5) = 8/0.5`.

The sum is **16**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00060', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 59, 'If log base x of 81 equals 4 (log_x 81 = 4), find the value of x.', 'The equation `log_x 81 = 4` means `x⁴ = 81`.

Since `81 = 3⁴`, we get `x⁴ = 3⁴`.

So `x = **3**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00061', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 60, 'In a triangle, the three angles are in the ratio 2:3:4. Find the measure of the largest angle.', 'Let the angles be `2k, 3k, 4k`. Since angles of a triangle sum to 180°: `2k + 3k + 4k = 180°`, giving `9k = 180°`, so `k = 20°`.

The largest angle = `4k = 4 × 20° = **80°**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00062', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 61, 'The sides of a triangle are 7 cm, 24 cm and 25 cm. Find its area.', 'Check if this is a right triangle: `7² + 24² = 49 + 576 = 625 = 25²`. Since this holds, the triangle is **right-angled**, with the right angle between the sides 7 cm and 24 cm.

Area of a right triangle = `(1/2) × base × height = (1/2) × 7 × 24`.

Area = **84 cm²**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00063', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 62, 'Two parallel chords of lengths 16 cm and 12 cm lie on opposite sides of the centre of a circle of radius 10 cm. Find the distance between the chords.', 'For the 16 cm chord: half-length = 8 cm, so its distance from the centre = `√(10² - 8²) = √(100-64) = √36 = 6 cm`.

For the 12 cm chord: half-length = 6 cm, so its distance from the centre = `√(10² - 6²) = √(100-36) = √64 = 8 cm`.

Since the chords lie on **opposite sides** of the centre, the total distance between them = `6 + 8 = **14 cm**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00064', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 63, 'Find the length of the diagonal of a rectangle with length 12 cm and breadth 5 cm.', 'The diagonal of a rectangle forms the hypotenuse of a right triangle with the length and breadth as the two legs.

Diagonal = `√(12² + 5²) = √(144 + 25) = √169`.

Diagonal = **13 cm**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00065', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 64, 'Find the distance between the points (3, 4) and (7, 1) on a coordinate plane.', 'Using the distance formula `d = √[(x₂-x₁)² + (y₂-y₁)²]`:

`d = √[(7-3)² + (1-4)²] = √[16 + 9] = √25`.

The distance is **5 units**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00066', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 65, 'Find the area of the triangle formed by the points (0,0), (4,0) and (0,3) on the coordinate plane.', 'Since two sides of this triangle lie along the x-axis and y-axis, it is a right triangle with legs of length 4 (base) and 3 (height).

Area = `(1/2) × base × height = (1/2) × 4 × 3`.

Area = **6 square units**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00067', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 66, 'In triangle ABC, D and E are the midpoints of sides AB and AC respectively. If DE = 6 cm, find the length of BC.', 'By the **Midpoint Theorem**, the segment joining the midpoints of two sides of a triangle is parallel to the third side and equal to half its length: `DE = (1/2) × BC`.

So `BC = 2 × DE = 2 × 6`.

`BC = **12 cm**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00068', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 67, 'A circle is inscribed in an equilateral triangle of side 12 cm. Find the radius of the inscribed circle.', 'For an equilateral triangle of side `a`, the inradius is given by `r = a / (2√3) = a√3/6`.

Here, `r = 12√3/6 = 2√3`.

The radius is `2√3 cm ≈ **3.46 cm**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00069', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 68, 'Find the volume of a cylinder with radius 7 cm and height 10 cm. (Use π = 22/7)', 'Volume of a cylinder is given by `V = πr²h`.

`V = (22/7) × 7² × 10 = (22/7) × 49 × 10 = 22 × 7 × 10`.

Volume = **1540 cm³**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00070', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 69, 'The curved surface area of a cone is 550 cm² and its base radius is 7 cm. Find its slant height. (Use π = 22/7)', 'Curved surface area of a cone is given by `CSA = πrl`, where `l` is the slant height.

`550 = (22/7) × 7 × l = 22l`.

Solving, `l = 550/22 = **25 cm**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00071', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 70, 'Find the total surface area of a cube whose volume is 216 cm³.', 'If the side of the cube is `a`, then `a³ = 216`, which gives `a = 6 cm` (since `6³ = 216`).

Total surface area of a cube = `6a²  = 6 × 6²= 6 × 36`.

Total surface area = **216 cm²**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00072', 'mba-entrance-bank', 'Quantitative Aptitude', 0, 71, 'Find the surface area of a sphere with radius 7 cm. (Use π = 22/7)', 'Surface area of a sphere is given by `SA = 4πr²`.

`SA = 4 × (22/7) × 7² = 4 × 22 × 7`.

Surface area = **616 cm²**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00073', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 0, 'Passage: "Behavioural economists argue that humans are not the purely rational calculators that classical economic theory assumes. Instead, people rely on mental shortcuts, or heuristics, that often lead to predictable errors in judgment. Recognising these biases has allowed policymakers to design ''nudges'' — small changes in how choices are presented — that steer people toward better decisions without restricting their freedom to choose." What is the central idea of this passage?', 'The passage argues that because real human decision-making departs predictably from pure rationality (through **heuristics and biases**), this understanding can be used to design **''nudges''** that improve choices while preserving freedom of choice.

The key contrast being drawn is between the **classical rational-agent model** and the **behavioural, bias-prone model** of decision-making, with nudging as the practical application of the latter.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00074', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 1, 'Passage: "The gig economy has expanded rapidly, offering workers flexibility that traditional employment rarely provides. Yet this flexibility comes at a cost: gig workers typically lack the job security, health benefits, and retirement contributions that accompany full-time employment. Several governments are now debating whether gig workers should be reclassified as employees rather than independent contractors." What tension does the passage primarily highlight?', 'The passage highlights the tension between the **flexibility** that gig work offers and the **lack of traditional employment protections** (job security, benefits, retirement contributions) that gig workers forgo.

This tension is what has triggered the regulatory debate mentioned at the end — whether to **reclassify gig workers as employees** to extend these protections, potentially at the cost of the flexibility that defines gig work.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00075', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 2, 'Passage: "Urbanisation in developing economies has often outpaced the growth of infrastructure. Cities swell with migrants seeking work, but housing, sanitation, and transport systems lag behind, resulting in sprawling informal settlements. Paradoxically, these same cities remain powerful engines of economic growth, generating a disproportionate share of national GDP despite their visible strains." What paradox does the author point to?', 'The paradox is that cities experiencing severe **infrastructure strain** (inadequate housing, sanitation, transport, leading to informal settlements) simultaneously function as the **strongest engines of national economic growth**, generating a disproportionate share of GDP.

In other words, visible urban dysfunction coexists with — and does not prevent — outsized economic contribution.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00076', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 3, 'Passage: "Central banks typically raise interest rates to curb inflation, since higher rates make borrowing more expensive and saving more attractive, which cools consumer spending. However, this tool is blunt: it slows the entire economy, including sectors unrelated to the original source of inflationary pressure, and can push a fragile economy into recession." According to the passage, why is raising interest rates described as a ''blunt'' tool?', 'It is called blunt because it **slows down the entire economy indiscriminately** — including sectors that had nothing to do with causing the inflation — rather than targeting only the specific source of inflationary pressure.

The passage also notes the risk that this broad slowdown can tip a **fragile economy into recession**, reinforcing the idea that the tool lacks precision.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00077', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 4, 'Passage: "Renewable energy sources such as solar and wind are intermittent by nature — they generate power only when the sun shines or the wind blows. This intermittency has historically been renewable energy''s greatest weakness, but advances in battery storage technology are steadily closing the gap, allowing excess energy generated during peak conditions to be stored and released when generation is low." What role does battery storage play according to the passage?', 'Battery storage is presented as the **solution to intermittency**, the chief historical weakness of renewables: it allows energy generated during peak sun/wind conditions to be **stored and released later** when generation drops.

This effectively decouples the *timing* of power generation from the *timing* of power consumption.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00078', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 5, 'Passage: "Many multinational corporations have adopted a ''glocal'' strategy — standardising their core product globally while adapting marketing, packaging, or even recipes to local tastes. This balances the cost efficiencies of global scale with the market responsiveness that purely local competitors can offer." What does the term ''glocal'' strategy balance, per the passage?', 'It balances the **cost efficiencies of global standardisation** (economies of scale from a uniform core product) against the **market responsiveness of local adaptation** (customised marketing, packaging, or recipes).

The strategy is essentially a hybrid designed to capture the advantages of both global scale and local relevance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00079', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 6, 'Passage: "Automation has historically displaced routine, repetitive tasks, pushing workers toward jobs requiring creativity, judgment, and interpersonal skills. Some economists warn, however, that newer generative AI tools are, for the first time, encroaching on precisely these ''safe'' cognitive and creative tasks, raising the question of which jobs, if any, remain insulated from automation." What new concern does the passage raise about generative AI?', 'The new concern is that generative AI is affecting a **different category of work** than earlier automation — not just routine, repetitive tasks, but the **creative and cognitive tasks** (judgment, interpersonal and creative skills) that were previously assumed to be safe from automation.

This raises the broader question of whether **any job category remains insulated** from automation going forward.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00080', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 7, 'Passage: "Supply chains that were optimised purely for cost efficiency, often by concentrating production in a single low-cost country, proved fragile during recent global disruptions. Many firms are now pursuing a ''just-in-case'' model that emphasises redundancy and diversification of suppliers, even though this raises operating costs compared with the earlier ''just-in-time'' approach." What trade-off does the passage describe?', 'The trade-off is between **cost efficiency** (the ''just-in-time'' model, with single-source, low-cost production) and **supply chain resilience** (the ''just-in-case'' model, with redundant and diversified suppliers).

Firms are shown to be accepting **higher operating costs** in exchange for being less fragile to disruption.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00081', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 8, 'Passage: "Microfinance institutions were originally conceived to provide small loans to entrepreneurs excluded from formal banking, enabling them to build small businesses and escape poverty. Critics now argue that some microfinance lenders charge high effective interest rates and aggressively pursue repayment, trapping some borrowers in cycles of debt rather than lifting them out of poverty." What criticism of microfinance does the passage present?', 'The criticism is that some microfinance lenders, despite the sector''s original poverty-alleviation purpose, charge **high effective interest rates** and pursue **aggressive repayment practices**, which can trap borrowers in **cycles of debt** instead of helping them escape poverty.

This highlights a gap between microfinance''s founding intent and its practical outcomes in some cases.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00082', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 9, 'Passage: "Economic inequality within nations has risen even as global inequality between nations has, by some measures, declined — largely because fast-growing emerging economies like China and India have narrowed the income gap with wealthier nations, even as inequality has widened within each of these countries." What apparent contradiction does the passage resolve?', 'The apparent contradiction is that global (between-country) inequality can **fall** while inequality within individual countries **rises** at the same time.

The resolution given is that fast-growing emerging economies narrowed the **average income gap with richer nations**, even though the gains within those emerging economies were **unevenly distributed**, widening inequality internally.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00083', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 10, 'Arrange the following sentences in a logical order to form a coherent paragraph.

A. This gap between forecast and outcome often stems from unmodeled behavioural responses to policy changes.
B. Economic forecasting models, however sophisticated, routinely fail to predict major turning points such as recessions.
C. As a result, many economists now advocate supplementing quantitative models with qualitative judgment.
D. For instance, people may save more than models predict when faced with fear of job loss, even if income remains stable.', 'The correct order is **B-A-D-C**.

**B** introduces the general claim (forecasting models fail at turning points). **A** explains the cause (unmodeled behavioural responses). **D** gives a concrete example of such a behavioural response. **C** closes with the resulting recommendation (supplementing models with judgment).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00084', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 11, 'Arrange the following sentences in a logical order to form a coherent paragraph.

A. Consequently, many firms have begun training employees to work alongside AI tools rather than be replaced by them.
B. Artificial intelligence is increasingly capable of performing tasks once considered uniquely human, such as drafting legal contracts or diagnosing diseases.
C. This capability does not necessarily mean wholesale job elimination, since most roles involve a bundle of tasks, only some of which AI can perform.
D. Studies suggest that this complementary approach, rather than pure substitution, yields the largest productivity gains.', 'The correct order is **B-C-A-D**.

**B** opens with AI''s growing capability. **C** qualifies this by noting roles involve task bundles, not full automation. **A** draws the practical consequence (training employees to work alongside AI). **D** adds supporting evidence that this complementary approach yields the best results.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00085', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 12, 'Arrange the following sentences in a logical order to form a coherent paragraph.

A. Yet overconfidence itself is a well-documented cognitive bias, meaning entrepreneurs often underestimate the odds of failure.
B. Most new businesses fail within their first five years, a statistic widely known even to first-time founders.
C. This combination of known risk and persistent optimism helps explain why entrepreneurship continues despite discouraging odds.
D. Despite this knowledge, founders typically proceed with striking confidence in their own venture''s prospects.', 'The correct order is **B-D-A-C**.

**B** states the known risk (high failure rate). **D** notes founders proceed confidently despite this. **A** explains this confidence as the cognitive bias of overconfidence. **C** concludes by tying the risk and the bias together to explain why entrepreneurship persists.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00086', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 13, 'Arrange the following sentences in a logical order to form a coherent paragraph.

A. Deforestation for agriculture is the primary driver, as forests are cleared to grow crops like soy and palm oil, or to raise cattle.
B. Tropical rainforests, despite covering less than ten percent of Earth''s land surface, host more than half of all known plant and animal species.
C. Protecting these ecosystems therefore carries significance far beyond their geographic footprint.
D. This extraordinary biodiversity is under threat from large-scale deforestation.', 'The correct order is **B-D-A-C**.

**B** establishes the fact about rainforest biodiversity relative to land area. **D** introduces the threat to this biodiversity. **A** explains the main cause of that threat (deforestation for agriculture). **C** concludes with the broader significance of protecting these ecosystems.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00087', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 14, 'Arrange the following sentences in a logical order to form a coherent paragraph.

A. However, critics note that such credentials often measure a firm''s reporting practices more than its actual environmental impact.
B. Consequently, investors are increasingly demanding independent verification rather than relying on self-reported sustainability metrics.
C. A growing number of companies now seek ESG (Environmental, Social, and Governance) certifications to attract socially conscious investors.
D. This gap between perception and reality has fuelled accusations of ''greenwashing.''', 'The correct order is **C-A-D-B**.

**C** introduces the trend of firms seeking ESG certification. **A** raises the criticism that these credentials measure reporting, not real impact. **D** names the resulting phenomenon (greenwashing). **B** concludes with the practical consequence — investors demanding independent verification.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00088', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 15, 'Arrange the following sentences in a logical order to form a coherent paragraph.

A. Unlike earlier generations, millennials and Gen Z employees frequently cite workplace flexibility as more important than salary alone.
B. Employers who fail to adapt risk higher attrition, since younger employees are more willing to switch jobs for better work-life balance.
C. This shift is forcing many organisations to redesign policies around remote work, flexible hours, and outcome-based evaluation.
D. Workplace priorities have shifted markedly across generations over the past two decades.', 'The correct order is **D-A-C-B**.

**D** opens with the general claim about shifting workplace priorities. **A** specifies the shift (flexibility over salary for younger employees). **C** describes the organisational response (redesigning policies). **B** closes with the consequence of failing to adapt (higher attrition).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00089', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 16, 'Arrange the following sentences in a logical order to form a coherent paragraph.

A. For example, a 1% rise in a currency''s value can make a country''s exports proportionally more expensive abroad.
B. A country''s currency exchange rate directly affects the competitiveness of its exporters in global markets.
C. Governments and central banks are therefore often tempted to intervene in currency markets to maintain export competitiveness.
D. Such interventions, however, can invite accusations of currency manipulation from trading partners.', 'The correct order is **B-A-C-D**.

**B** states the general relationship between exchange rates and export competitiveness. **A** illustrates it with a concrete example. **C** describes the resulting policy temptation (intervention). **D** closes with the risk this intervention carries (accusations of manipulation).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00090', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 17, 'Arrange the following sentences in a logical order to form a coherent paragraph.

A. These algorithms analyse browsing history, purchase patterns, and even time spent viewing an item to predict what a customer is likely to buy next.
B. E-commerce platforms increasingly rely on recommendation algorithms to personalise the shopping experience.
C. Such precision raises concerns about privacy, as the sheer volume of behavioural data collected can reveal sensitive details about a person''s life.
D. The result is a feed of suggestions that can feel remarkably accurate, sometimes anticipating needs the shopper had not consciously articulated.', 'The correct order is **B-A-D-C**.

**B** introduces recommendation algorithms. **A** explains how they work (analysing behavioural data). **D** describes the resulting outcome (accurate, anticipatory suggestions). **C** closes with the privacy concern this precision raises.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00091', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 18, 'Arrange the following sentences in a logical order to form a coherent paragraph.

A. This long-held assumption has been challenged by evidence that sustained attention to a single difficult task, without interruption, often produces superior results.
B. Multitasking has long been praised as a valuable skill in fast-paced workplaces.
C. Deep work, as this focused mode is now called, requires deliberately eliminating distractions such as notifications and open browser tabs.
D. Many productivity experts now recommend scheduling blocks of uninterrupted time specifically for cognitively demanding work.', 'The correct order is **B-A-C-D**.

**B** opens with the conventional praise for multitasking. **A** challenges this with the counter-evidence about focused attention. **C** names and defines this alternative mode (''deep work''). **D** closes with the practical recommendation that follows from it.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00092', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 19, 'Paragraph Summary: "Despite decades of research, there is no universally accepted definition of intelligence. IQ tests measure certain logical and verbal reasoning abilities well but are criticised for overlooking creativity, emotional understanding, and practical problem-solving skills that matter greatly in real life. Multiple-intelligence theories have tried to broaden the concept, though they remain difficult to measure objectively, leaving the field without a single, agreed-upon yardstick." Which of the following best summarises the passage?', 'The best summary is that **intelligence lacks a single, universally accepted definition or measure** — traditional IQ tests capture only part of it (logical/verbal reasoning) while missing creativity, emotional, and practical abilities, and alternative theories that try to broaden the concept remain hard to measure objectively.

An overly narrow summary (e.g., ''IQ tests are flawed'') would miss the passage''s broader point about the **absence of any single adequate measure of intelligence**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00093', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 20, 'Paragraph Summary: "Universal Basic Income (UBI) proposes giving every citizen a fixed, unconditional cash payment regardless of income or employment status. Proponents argue it could reduce poverty and provide a safety net amid automation-driven job losses. Critics counter that it is prohibitively expensive at scale and may reduce the incentive to work, though pilot programmes have so far shown mixed effects on labour participation." Which summary best captures this passage?', 'The best summary is that **UBI is a debated policy proposal**: supporters see it as a poverty-reduction tool suited to an automating economy, while critics cite its cost and possible work disincentives, and real-world pilots have so far produced **mixed, inconclusive evidence** on the labour-participation question.

A summary that states only ''UBI reduces poverty'' or only ''UBI discourages work'' would be **incomplete**, since the passage presents both sides and notes the evidence remains unsettled.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00094', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 21, 'Paragraph Summary: "Franchising allows a business owner to expand rapidly by licensing their brand, systems, and operating procedures to independent franchisees who invest their own capital. The franchisor benefits from faster growth with lower capital outlay, while franchisees gain a tested business model and brand recognition. The arrangement can strain, however, when franchisees feel head-office rules are too rigid for their local market." Which summary best captures this passage?', 'The best summary: franchising lets a **franchisor expand quickly with limited capital** by licensing its brand and systems to **franchisees**, who in turn get a proven model and brand recognition — but the relationship can become strained when **rigid corporate rules clash with local market needs**.

A summary focusing only on the benefits, without mentioning the tension over rigid rules, would be **incomplete**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00095', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 22, 'Paragraph Summary: "Patent systems are designed to reward innovation by granting inventors a temporary monopoly over their creation, encouraging investment in research. Critics argue that in some industries, notably pharmaceuticals, this same monopoly can keep life-saving drug prices high for years, delaying affordable generic alternatives and raising questions about how to balance innovation incentives against public access." Which summary best captures this passage?', 'The best summary: patents exist to **incentivise innovation** through temporary monopolies, but in sectors like pharmaceuticals this same mechanism can **keep prices high and delay generics**, creating a genuine policy tension between **rewarding innovation and ensuring public access**.

A one-sided summary emphasising only the innovation benefit, or only the access problem, would miss the passage''s central **trade-off framing**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00096', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 23, 'Paragraph Summary: "Remote work expanded dramatically during the pandemic and has persisted since, as many employees report higher productivity and better work-life balance when working from home. However, managers increasingly worry about weaker mentorship for junior staff, who learn less by informal observation when they are not physically present with experienced colleagues." Which summary best captures this passage?', 'The best summary: remote work has **persisted post-pandemic** because employees often report gains in productivity and work-life balance, but this shift raises concern among managers about **weaker informal mentorship for junior employees** who miss out on learning by observation.

A summary citing only the productivity benefits, without the mentorship concern, would be **one-sided and incomplete**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00097', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 24, 'Critical Reasoning: "A city council argues that building a new highway bypass will reduce traffic congestion in the city centre, since through-traffic will no longer need to pass downtown." Which of the following, if true, would most weaken this argument?', 'The argument would be most weakened by evidence that **the bypass will induce additional overall traffic demand** — for instance, that new housing and commercial development along the bypass route will generate so much new local traffic that overall congestion in the city centre does not meaningfully fall, or even rises, a phenomenon known as **''induced demand.''**

This directly attacks the causal link assumed by the council — that diverting through-traffic necessarily reduces downtown congestion — by introducing a countervailing source of new traffic.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00098', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 25, 'Critical Reasoning: "A pharmaceutical company claims its new drug is effective because patients who took it reported feeling better within a week." What is the main flaw in this reasoning?', 'The main flaw is the **absence of a control group** (a comparable group not given the drug, ideally with a placebo). Without comparing outcomes to patients who did not take the drug, the improvement cannot be confidently attributed to the drug itself.

Patients may have improved due to the **placebo effect**, the natural course of the illness, or other unrelated factors — the reasoning confuses correlation (improvement after taking the drug) with causation (improvement because of the drug).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00099', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 26, 'Critical Reasoning: "Company X notes that employee satisfaction scores rose after it introduced a four-day work week, and concludes that shorter work weeks boost employee satisfaction." What assumption is necessary for this conclusion to hold?', 'The argument necessarily assumes that **no other significant change occurred at the same time** that could independently explain the rise in satisfaction — for example, a simultaneous pay rise, change in management, or improved office environment.

If such a confounding factor existed, the satisfaction increase could be due to that factor rather than the shorter work week, undermining the stated conclusion.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00100', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 27, 'Critical Reasoning: "A nutritionist argues that since countries with higher chocolate consumption per capita have more Nobel laureates per capita, eating chocolate improves cognitive ability." What is the primary logical flaw in this argument?', 'This is a classic case of mistaking **correlation for causation**. A statistical association between two variables (chocolate consumption and Nobel laureates per capita) does not establish that one causes the other.

A more plausible explanation is a **confounding variable** — national wealth — since wealthier countries tend to both consume more chocolate and invest more in research and education that produces Nobel laureates.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00101', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 28, 'Critical Reasoning: "An airline argues that it should not be required to compensate passengers for weather-related flight delays, since weather is beyond the airline''s control." Which of the following, if true, would most weaken this argument?', 'The argument would be most weakened by evidence that the airline **could have mitigated the delay through its own scheduling and operational decisions** — for instance, that it is common industry practice to build buffer time into schedules for forecast weather disruptions, and that other airlines flying the same routes experienced significantly shorter delays.

This challenges the implicit assumption that the delay''s length was **entirely** dictated by the weather itself, rather than partly by the airline''s own planning choices.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00102', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 29, 'Critical Reasoning: "A city reports that since installing speed cameras on a major road, the number of recorded speeding violations has fallen by 40%, and concludes that the cameras have made the road safer." What alternative explanation could undermine this conclusion?', 'The fall in **recorded** violations may simply reflect that drivers only slow down near the known camera locations and then speed up again afterward, meaning overall safety on the full stretch of road, including accident rates, may not have improved at all.

This distinguishes between a reduction in **measured violations at specific points** and genuine improvement in **overall road safety**, which the conclusion assumes but the evidence does not directly establish.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00103', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 30, 'Critical Reasoning: "A startup''s founder argues, ''Our competitor failed despite having more funding than us, so funding levels clearly don''t determine startup success.''" What is the flaw in this reasoning?', 'The flaw is drawing a **general causal rule from a single counter-example**. One failed well-funded competitor does not establish that funding is irrelevant to success in general — it only shows that funding alone is not **sufficient** for success, not that it is **unimportant**.

Many other factors (product-market fit, execution, timing) could explain the competitor''s failure despite adequate funding, while funding might still meaningfully improve the odds of success on average across many startups.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00104', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 31, 'Critical Reasoning: "A government minister argues that raising the minimum wage will not increase unemployment, citing a recent study of one city that raised its minimum wage with no detectable rise in joblessness." What is a reasonable critique of using this evidence to support a general policy conclusion?', 'A reasonable critique is that **a single city''s experience may not generalise** to other regions or to the economy as a whole — local labour market conditions, industry mix, and the size of the wage increase in that specific study may differ substantially from conditions elsewhere.

Drawing a nationwide policy conclusion from **one localized study** risks overgeneralising from a limited and potentially unrepresentative sample.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00105', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 32, 'Critical Reasoning: "An investor states, ''This stock has risen every year for the past five years, so it is certain to rise again next year.''" What is the central flaw in this argument?', 'The flaw is assuming that a **past trend guarantees future performance**, ignoring that stock prices are influenced by changing market conditions, company fundamentals, and macroeconomic factors that are not bound to repeat a historical pattern.

Past performance, however consistent, is **not a guarantee of future results** — a principle widely recognised in finance precisely because trends can reverse due to factors unrelated to the stock''s own history.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00106', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 33, 'Critical Reasoning: "A school principal argues that because students who attend the school''s optional weekend coaching classes score higher on exams, the coaching classes are responsible for better performance, and should be made mandatory for all students." What assumption does this argument rely on?', 'The argument assumes that students who **chose** to attend the optional classes are comparable to those who did not — in particular, it assumes there is no **selection bias**, such as more motivated or academically stronger students being more likely to opt into extra coaching in the first place.

If more capable or driven students self-selected into the coaching classes, their higher scores might reflect their pre-existing motivation or ability rather than any benefit from the coaching itself.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00107', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 34, 'Odd one out: Which of the following does not belong with the others — Inflation, Deflation, Stagflation, Depreciation?', '**Depreciation** is the odd one out.

**Inflation**, **Deflation**, and **Stagflation** all describe conditions of the **general price level** in an economy (prices rising, falling, or rising alongside stagnant growth and high unemployment, respectively). **Depreciation**, by contrast, refers to a **fall in the value of a specific currency relative to other currencies** (or the reduction in asset value over time), not the economy-wide price level.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00108', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 35, 'Odd one out: Which of the following does not belong with the others — Merger, Acquisition, Amalgamation, Dividend?', '**Dividend** is the odd one out.

**Merger**, **Acquisition**, and **Amalgamation** all describe ways in which **two or more companies combine or one absorbs another**. A **Dividend**, in contrast, is a **distribution of a company''s profits to its shareholders** and has nothing to do with corporate combination.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00109', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 36, 'Odd one out: Which of the following does not belong with the others — Equity, Debenture, Bond, Audit?', '**Audit** is the odd one out.

**Equity**, **Debenture**, and **Bond** are all **financial instruments** that a company can issue to raise capital (ownership stake or forms of debt). An **Audit**, on the other hand, is a process of **independently examining financial records for accuracy**, not an instrument for raising funds.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00110', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 37, 'Odd one out: Which of the following does not belong with the others — Tariff, Quota, Subsidy, Depreciation (currency)?', '**Depreciation (currency)** is the odd one out.

**Tariff**, **Quota**, and **Subsidy** are all **deliberate government policy tools** used to influence trade and protect domestic industries (a tax on imports, a limit on import quantity, and financial support to domestic producers, respectively). **Currency depreciation** is a **market or macroeconomic outcome** (a fall in a currency''s value), not itself a discrete policy instrument of trade protection, even though it can be influenced by policy.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00111', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 38, 'Fill in the blank with the most appropriate word: "The committee''s findings were so _____ that even its harshest critics found little room to disagree."', 'The most appropriate word is **''incontrovertible''** (or a close synonym such as ''unassailable''), meaning not able to be denied or disputed.

This fits the context because the sentence explicitly states that even the harshest critics found **little room to disagree** — implying the findings were beyond reasonable dispute.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00112', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 39, 'Fill in the blank with the most appropriate word: "Despite the recession, the company''s revenues remained _____, neither growing nor shrinking significantly over the two-year period."', 'The most appropriate word is **''stagnant''** (or ''static''/''flat''), meaning showing no growth or development.

This fits because the sentence explicitly clarifies the meaning it needs — revenues **''neither growing nor shrinking significantly''** — which is the precise definition of stagnation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00113', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 40, 'Fill in the blank with the most appropriate word: "The negotiator''s _____ manner put both sides at ease, allowing a deal to be reached where previous attempts had failed."', 'The most appropriate word is **''conciliatory''**, meaning intended to placate or pacify, showing a willingness to compromise.

This fits the context because the word must describe a manner that **''put both sides at ease''** and enabled a successful deal after prior failures — the hallmark of a conciliatory approach, as opposed to an aggressive or confrontational one.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00114', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 41, 'Fill in the blank with the most appropriate word: "The CEO''s memo was deliberately _____, leaving employees uncertain about whether layoffs were actually being planned."', 'The most appropriate word is **''ambiguous''** (or ''equivocal''), meaning open to more than one interpretation.

This fits the context because the sentence explicitly states the outcome of the word choice — employees were left **''uncertain''** about the memo''s true meaning, which is the defining effect of ambiguity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00115', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 42, 'Fill in the blank with the most appropriate word: "Rather than confronting the problem directly, the manager chose to _____ the issue in every meeting, hoping it would resolve itself."', 'The most appropriate word is **''sidestep''** (or ''circumvent''/''evade''), meaning to avoid dealing with something directly.

This fits because the sentence sets up an explicit contrast — **''rather than confronting... directly''** — so the blank must denote the opposite behaviour: avoidance rather than direct engagement.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00116', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 43, 'Choose the correctly constructed sentence.

(A) Neither the manager nor the employees was aware of the policy change.
(B) Neither the manager nor the employees were aware of the policy change.
(C) Neither the manager or the employees were aware of the policy change.
(D) Neither the manager and the employees was aware of the policy change.', '**(B)** is correct: "Neither the manager nor the employees **were** aware of the policy change."

Two grammar rules apply here. First, ''neither...nor'' is the correct paired conjunction (not ''neither...or'', ruling out C, and not ''neither...and'', ruling out D). Second, with ''neither...nor'', the verb agrees with the **noun closest to it** — here, ''employees'' (plural) — so the verb must be **''were''**, not ''was'', ruling out A.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00117', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 44, 'Choose the correctly constructed sentence.

(A) The data suggests that consumer confidence is rising.
(B) The data suggest that consumer confidence is rising.
(C) The datas suggest that consumer confidence is rising.
(D) The data suggesting that consumer confidence is rising.', 'In formal/traditional usage, **(B)** is considered most correct: "The data **suggest** that consumer confidence is rising."

This is because ''data'' is traditionally treated as the **plural of ''datum''**, requiring a plural verb (''suggest''). Option A reflects common informal usage (treating ''data'' as singular/mass noun), but in formal written English and most standardised tests, the plural agreement in B is preferred. ''Datas'' (C) is not a standard English word, and D lacks a main verb, making it a sentence fragment.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00118', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 45, 'Choose the correctly constructed sentence.

(A) Each of the departments have submitted their budget reports.
(B) Each of the departments has submitted its budget report.
(C) Each of the department have submitted their budget reports.
(D) Each of the departments has submitted their budget reports.', '**(B)** is correct: "Each of the departments **has** submitted **its** budget report."

''Each'' is a singular indefinite pronoun, so it takes a **singular verb** (''has'', not ''have'') and should be followed by a **singular possessive** (''its'', not ''their'') for strict grammatical agreement, ruling out A, C (wrong plural ''department''), and D (mismatched ''their'').', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00119', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 46, 'Choose the correctly constructed sentence.

(A) The number of applicants have increased significantly this year.
(B) The number of applicants has increased significantly this year.
(C) A number of applicants has increased significantly this year.
(D) The numbers of applicants has increased significantly this year.', '**(B)** is correct: "The number of applicants **has** increased significantly this year."

The key rule: **''The number of''** is treated as singular (takes ''has''), while **''A number of''** is treated as plural (would take ''have''). Since the sentence uses ''The number of'', option B is correct; C incorrectly pairs ''A number of'' with a singular verb, and D awkwardly pluralises ''numbers''.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00120', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 47, 'Choose the correctly constructed sentence.

(A) She is one of the executives who has consistently exceeded their targets.
(B) She is one of the executives who have consistently exceeded their targets.
(C) She is one of the executive who have consistently exceeded their targets.
(D) She is one of the executives who has consistently exceeded her targets.', '**(B)** is correct: "She is one of the executives **who have** consistently exceeded their targets."

In the construction ''one of the [plural noun] who...'', the relative pronoun ''who'' refers back to the **plural noun** (''executives''), not to ''she'' alone, so the verb must agree with the plural antecedent: **''have''**, not ''has''. This rules out A and D; C incorrectly uses the singular ''executive''.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00121', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 48, 'Analogy: SCALPEL is to SURGEON as GAVEL is to ____?', '**JUDGE**.

The relationship is ''tool of the trade'': a **scalpel** is the characteristic instrument wielded by a **surgeon** in performing their role, just as a **gavel** is the characteristic instrument wielded by a **judge** (to call order or signal a ruling) in performing theirs.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00122', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 49, 'Analogy: AUSTERITY is to GOVERNMENT SPENDING as RATIONING is to ____?', '**CONSUMPTION (of scarce goods).**

The relationship is ''deliberate restriction of a resource'': **austerity** refers to the deliberate curbing of **government spending** (often to reduce deficits), just as **rationing** refers to the deliberate restriction of **consumption** of a scarce good (often during shortages, such as wartime), controlling how much of it individuals may use.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00123', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 50, 'Analogy: INFLATION is to PURCHASING POWER as EROSION is to ____?', '**TOPSOIL (or land/soil fertility).**

The relationship is ''a gradual process that diminishes a valuable resource over time'': **inflation** gradually diminishes the **purchasing power** of money, just as **erosion** gradually diminishes the quantity and quality of **topsoil**, degrading the land''s productive value over time.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00124', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 51, 'Analogy: MONOPOLY is to SINGLE SELLER as MONOPSONY is to ____?', '**SINGLE BUYER.**

The relationship is a direct structural parallel: a **monopoly** is a market structure with only **one seller** facing many buyers, whereas a **monopsony** is the mirror-image market structure with only **one buyer** facing many sellers (e.g., a single large employer in a local labour market).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00125', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 52, 'Analogy: PROTOTYPE is to PRODUCT as DRAFT is to ____?', '**FINAL DOCUMENT (or manuscript/report).**

The relationship is ''preliminary version preceding the finished output'': a **prototype** is an early, testable version that precedes the finished **product**, just as a **draft** is an early, revisable version that precedes the finished **document**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00126', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 53, 'Analogy: CARTEL is to COLLUSION as DUOPOLY is to ____?', '**LIMITED COMPETITION (between two dominant firms).**

The relationship is ''market structure and its defining behaviour/characteristic'': a **cartel** is a market structure defined by explicit **collusion** among its members to fix prices or output, just as a **duopoly** is a market structure defined by **limited competition** confined to just two dominant firms, which may or may not collude.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00127', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 54, 'Analogy: AMORTISATION is to INTANGIBLE ASSET as DEPRECIATION is to ____?', '**TANGIBLE (FIXED) ASSET.**

The relationship is a direct accounting parallel: **amortisation** is the accounting term for systematically writing off the cost of an **intangible asset** (like a patent or goodwill) over its useful life, just as **depreciation** is the parallel term used for writing off the cost of a **tangible/fixed asset** (like machinery or a building).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00128', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 55, 'Analogy: WHISTLEBLOWER is to MISCONDUCT as AUDITOR is to ____?', '**FINANCIAL IRREGULARITIES (or inaccuracies in accounts).**

The relationship is ''role defined by the act of exposing or checking for wrongdoing'': a **whistleblower** is someone who exposes **misconduct**, typically from the inside, just as an **auditor** is someone whose formal role is to examine and detect **financial irregularities** or inaccuracies within an organisation''s accounts.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00129', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 56, 'Analogy: SUBSIDY is to ENCOURAGE as TARIFF is to ____?', '**DISCOURAGE (or restrict/deter).**

The relationship is ''policy tool and its intended directional effect'': a **subsidy** is a financial incentive used to **encourage** a particular activity (such as domestic production), just as a **tariff** is a tax used to **discourage** a particular activity (such as importing foreign goods) by raising its cost.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00130', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 57, 'Analogy: BULL MARKET is to OPTIMISM as BEAR MARKET is to ____?', '**PESSIMISM.**

The relationship is ''market condition and the investor sentiment that defines it'': a **bull market** is characterised by rising prices driven by investor **optimism**, just as a **bear market** is characterised by falling prices driven by investor **pessimism**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00131', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 58, 'Passage: "Network effects occur when a product or service becomes more valuable to each user as more people use it, as seen with social media platforms and payment apps. This dynamic can create powerful, self-reinforcing growth for early market leaders, but it also raises antitrust concerns, since it can entrench a dominant firm''s position long after a rival might otherwise have offered a superior product." What concern does the passage raise about network effects?', 'The concern is that network effects, while driving legitimate self-reinforcing growth for early leaders, can also **entrench a dominant firm''s market position** in a way that is difficult for rivals to dislodge — even if a competitor later offers a **superior product** — which is why the phenomenon attracts **antitrust (competition-policy) scrutiny**.

The key insight is that network effects can make market dominance **self-perpetuating** independent of ongoing product quality.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00132', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 59, 'Passage: "Vertical integration occurs when a company controls multiple stages of its supply chain, such as a car manufacturer that also owns its parts suppliers. This can reduce costs and improve coordination, but it also concentrates risk, since a disruption at any single owned stage — a strike, a factory fire — can halt the entire chain, whereas a diversified set of external suppliers might allow a firm to simply switch sources." What trade-off does vertical integration present, according to the passage?', 'The trade-off is between **cost and coordination benefits** (lower costs, tighter coordination across supply-chain stages under one roof) and **concentrated operational risk** (a disruption at any single owned stage can halt the entire chain, unlike relying on multiple external, substitutable suppliers).

In short, vertical integration gains **control and efficiency** at the cost of **resilience through diversification**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00133', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 60, 'Passage: "Sovereign wealth funds are state-owned investment funds, often built from a country''s surplus revenues such as oil exports, and are used to invest in global assets ranging from equities to real estate. Proponents see them as a prudent way to convert finite natural-resource wealth into a diversified, durable asset base for future generations, while critics worry about the lack of transparency in how some of these funds are governed and deployed." What is the central purpose of sovereign wealth funds, as described in the passage?', 'Their central purpose is to **convert a country''s finite, often resource-based surplus revenue (such as oil exports) into a diversified pool of global assets**, creating a **durable store of wealth for future generations** rather than letting the gains from a depletable resource simply be spent in the present.

The passage also flags a **governance/transparency concern** as a counterpoint to this intended benefit.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00134', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 61, 'Passage: "Behavioural ''loss aversion'' describes the tendency for people to feel the pain of a loss roughly twice as intensely as the pleasure of an equivalent gain. This asymmetry explains why investors often hold on to losing stocks far longer than winning ones, hoping to ''break even'' rather than realising a loss, even when selling and reallocating funds would be the more rational choice." According to the passage, what investing behaviour does loss aversion help explain?', 'Loss aversion helps explain why investors tend to **hold onto losing stocks for too long**, hoping to break even rather than crystallising the loss — even when, from a purely rational standpoint, selling and reallocating the funds elsewhere would be the better decision.

The underlying mechanism is the described **asymmetry in emotional impact**: a loss feels roughly twice as painful as an equivalent gain feels pleasurable, biasing the decision away from realising losses.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00135', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 62, 'Critical Reasoning: "An online retailer argues that since its sales rose by 30% immediately after a price cut, further price cuts will continue to boost total revenue." What is a key flaw in extending this conclusion?', 'The key flaw is assuming the relationship between price and sales volume is **linear and will hold indefinitely** in the same direction. In reality, demand responses to price changes typically follow a **diminishing or even reversing pattern** — at some point, further price cuts may fail to meaningfully boost volume, or may reduce per-unit margins so much that **total revenue actually falls**, even if units sold rise.

The argument wrongly generalises from **one successful instance** to an unlimited, repeatable strategy, ignoring that price elasticity of demand is not constant at every price level.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00136', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 63, 'Critical Reasoning: "A city''s health department notes that neighbourhoods with more fast-food outlets have higher rates of obesity, and concludes that fast-food outlets cause obesity in these areas." What alternative explanation could challenge this conclusion?', 'A plausible alternative is **reverse causation or a common confounding factor** — for instance, lower-income neighbourhoods may both attract more fast-food outlets (due to lower rents and strong demand for cheap food) and independently have higher obesity rates due to factors like limited access to affordable fresh produce, fewer safe spaces for exercise, or longer working hours.

In this case, **income level** (or a related factor) could be driving both the prevalence of fast-food outlets and the obesity rate, without fast food outlets being the direct cause of obesity themselves.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00137', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 64, 'Critical Reasoning: "A venture capitalist argues, ''Every unicorn startup I''ve funded pivoted from its original business idea at least once, so pivoting is the key to building a billion-dollar company.''" What is the flaw in this reasoning?', 'The flaw is **survivorship bias** — the investor is only examining the successful ''unicorn'' startups that pivoted, without checking how many startups that pivoted ultimately **failed** anyway, or how many that **never pivoted** also succeeded.

Without data on the full population of startups (both successes and failures, both pivoters and non-pivoters), it is impossible to conclude that pivoting is actually the **key causal factor** behind reaching billion-dollar status, rather than simply something many successful companies happened to have done.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00138', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 65, 'Odd one out: Which of the following does not belong with the others — Bond, Equity, Treasury Bill, Depreciation (asset)?', '**Depreciation (asset)** is the odd one out.

**Bond**, **Equity**, and **Treasury Bill** are all financial **instruments that can be bought and held as investments** (debt security, ownership stake, and short-term government debt, respectively). **Depreciation**, in contrast, is an **accounting concept** representing the reduction in the recorded value of a fixed asset over time — it is not an investable instrument.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00139', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 66, 'Odd one out: Which of the following does not belong with the others — Oligopoly, Monopoly, Perfect Competition, Arbitrage?', '**Arbitrage** is the odd one out.

**Oligopoly**, **Monopoly**, and **Perfect Competition** are all terms describing **market structures**, classified by the number of sellers and the degree of competition among them. **Arbitrage**, in contrast, is a **trading strategy** — simultaneously buying and selling an asset in different markets to profit from a price difference — and is not itself a market structure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00140', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 67, 'Fill in the blank with the most appropriate word: "The merger talks collapsed because the two boards could not reach a _____ on the valuation of the smaller company."', 'The most appropriate word is **''consensus''** (or ''agreement''), meaning general agreement among a group.

This fits because the sentence states the talks **''collapsed''** specifically over an inability to agree on valuation — exactly the situation a failure to reach consensus describes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00141', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 68, 'Fill in the blank with the most appropriate word: "The analyst''s report was criticised as _____, offering sweeping conclusions without the data to support them."', 'The most appropriate word is **''unsubstantiated''** (or ''speculative''), meaning not supported by evidence.

This fits because the sentence directly explains the criticism — the report drew **''sweeping conclusions without the data to support them''** — which is precisely what ''unsubstantiated'' means.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00142', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 69, 'Analogy: RECESSION is to ECONOMY as DROUGHT is to ____?', '**AGRICULTURE (or crop yield/land).**

The relationship is ''a period of severe scarcity or decline affecting a system'': a **recession** is a sustained period of decline affecting the **economy** broadly, just as a **drought** is a sustained period of water scarcity that severely affects **agriculture** and crop yields.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00143', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 70, 'Analogy: PATENT is to INVENTION as COPYRIGHT is to ____?', '**CREATIVE/LITERARY OR ARTISTIC WORK (such as a book, song, or film).**

The relationship is ''legal protection granted to a specific category of intellectual output'': a **patent** grants legal protection over an **invention**, just as a **copyright** grants legal protection over an original **creative or artistic work**, in each case giving the creator exclusive rights for a defined period.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00144', 'mba-entrance-bank', 'Verbal Ability & Reading Comprehension', 1, 71, 'Analogy: HEDGE FUND is to ACCREDITED INVESTORS as MUTUAL FUND is to ____?', '**RETAIL (GENERAL PUBLIC) INVESTORS.**

The relationship is ''investment vehicle and its typical investor base'': a **hedge fund** is generally restricted to **accredited (wealthy/institutional) investors** due to lighter regulation and higher risk, just as a **mutual fund** is designed to be broadly accessible to **retail investors**, being more heavily regulated for public participation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00145', 'mba-entrance-bank', 'Logical Reasoning', 2, 0, 'Five friends S, T, Q, R and P are seated in a row of 5 chairs numbered 1 to 5 from left to right. Q sits at position 3. R sits immediately to the right of Q. P sits at an extreme end, but not at position 1. T sits immediately to the left of Q. Determine the complete seating arrangement from position 1 to 5.', 'Since Q sits at position 3, and R sits immediately to its right, `R = position 4`.

P must occupy an extreme end (position 1 or 5) but not position 1, so `P = position 5`.

T sits immediately to the left of Q, so `T = position 2`. The only remaining position, 1, must then go to **S** by elimination.

The final order from position 1 to 5 is **S, T, Q, R, P**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00146', 'mba-entrance-bank', 'Logical Reasoning', 2, 1, 'Eight people A, B, C, D, E, F, G and H sit in a row facing north, numbered 1 to 8 from left to right. D sits at position 5. E sits immediately to the right of D. C sits at the extreme left end. B sits exactly midway between C and D. F sits immediately to the left of D. There are exactly two people between F and A, with A to the right of F. G and H occupy the two remaining positions, with G to the left of H. Who sits at position 8?', 'C is at the extreme left, so `C = 1`, and `D = 5` is given, so B, midway between them, sits at position `(1+5)/2 = 3`.

F sits immediately left of D, so `F = 4`. With two people between F and A (positions 5 and 6, occupied by D and E), `A = 4 + 3 = 7`.

The only positions left are 2 and 8; since G sits to the left of H, `G = 2` and `H = 8`.

The full arrangement is C, G, B, F, D, E, A, H — so position 8 is occupied by **H**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00147', 'mba-entrance-bank', 'Logical Reasoning', 2, 2, 'Seven books — A, B, C, D, E, F and G — are placed in a single stack, with position 1 being the topmost. A is at the very bottom. F is placed immediately above A. C is directly above E. There are exactly two books between G and C, with G above C. B is directly below D. Determine the complete order of the books from top to bottom.', 'Since A is at the very bottom of 7 books, `A = position 7`, and F sits immediately above it, so `F = position 6`.

This leaves positions 1–5 for G, D, B, C and E. Since C is directly above E, they must occupy two consecutive slots, `E = C + 1`; since there are exactly two books between G and C with G above, `G = C − 3`. For both `C − 3 ≥ 1` and `C + 1 ≤ 5` to hold, the only possible value is `C = 4`, giving `E = 5` and `G = 1`.

The only positions left, 2 and 3, go to D and B, and since B is directly below D, `D = 2, B = 3`.

The complete order from top to bottom is **G, D, B, C, E, F, A**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00148', 'mba-entrance-bank', 'Logical Reasoning', 2, 3, 'Six friends P, Q, R, S, T and U sit around a circular table, all facing the center, with positions numbered 1 to 6 clockwise. Q sits second to the right of P. R sits immediately to the left of Q. S sits directly opposite P. T sits immediately to the right of S. U occupies the only remaining seat. Who sits immediately to the left of T?', 'Taking P''s seat as position 1 and moving clockwise, Q, being second to the right of P, sits at `position 1 + 2 = 3`.

R, immediately to the left of Q, sits at `position 3 − 1 = 2`. S, directly opposite P in a 6-seat circle, sits at `position 1 + 3 = 4`.

T, immediately to the right of S, sits at `position 4 + 1 = 5`, leaving the one remaining seat, position 6, for U.

The seat immediately to the left of T (position 5) is position 4, which is occupied by **S**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00149', 'mba-entrance-bank', 'Logical Reasoning', 2, 4, 'Six friends A, B, C, D, E and F sit around a circular table, all facing the center, with seats numbered 1 to 6 clockwise, starting with A at seat 1. B sits third to the right of A. D sits second to the left of A. E sits immediately to the right of D. C sits immediately to the left of B. F occupies the one remaining seat. Who sits immediately to the right of A?', 'With A at seat 1, B, third to the right (clockwise), sits at `1 + 3 = 4`. D, second to the left (counter-clockwise), sits at `1 − 2 = 5` (wrapping around the 6-seat circle).

E, immediately to the right of D, sits at `5 + 1 = 6`. C, immediately to the left of B, sits at `4 − 1 = 3`.

The seats used so far are 1 (A), 3 (C), 4 (B), 5 (D), 6 (E), leaving seat 2 for **F**, which is also the seat immediately to the right of A.

So **F** sits immediately to the right of A.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00150', 'mba-entrance-bank', 'Logical Reasoning', 2, 5, 'Find the next number in the series: 2, 6, 12, 20, 30, ?', 'The differences between consecutive terms are `6-2=4`, `12-6=6`, `20-12=8`, `30-20=10` — increasing by 2 each time, so the next difference is `12`.

This matches the pattern `n(n+1)`: `1×2=2, 2×3=6, 3×4=12, 4×5=20, 5×6=30`, so the next term is `6×7 = 42`.

The next number is **42**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00151', 'mba-entrance-bank', 'Logical Reasoning', 2, 6, 'Find the next number in the series: 3, 8, 15, 24, 35, ?', 'Each term fits the pattern `n(n+2)`: `1×3=3, 2×4=8, 3×5=15, 4×6=24, 5×7=35`.

Following this pattern, the next term is `6×8 = **48**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00152', 'mba-entrance-bank', 'Logical Reasoning', 2, 7, 'Find the next term in the letter series: AZ, BY, CX, DW, ?', 'This series has two interleaved patterns: the first letter of each pair moves **forward** through the alphabet (A, B, C, D, ...) while the second letter moves **backward** (Z, Y, X, W, ...).

Continuing both patterns, the first letter after D is **E**, and the second letter after W is **V**.

The next term is **EV**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00153', 'mba-entrance-bank', 'Logical Reasoning', 2, 8, 'Find the next number in the Fibonacci-style series: 1, 1, 2, 3, 5, 8, 13, 21, ?', 'This is the classic **Fibonacci sequence**, where each term is the sum of the two preceding terms.

The last two terms are 13 and 21, so the next term is `13 + 21 = **34**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00154', 'mba-entrance-bank', 'Logical Reasoning', 2, 9, 'Find the next number in the series: 7, 26, 63, 124, 215, ?', 'Each term follows the pattern `n³ - 1`: `2³-1=7, 3³-1=26, 4³-1=63, 5³-1=124, 6³-1=215`.

Following this pattern, the next term is `7³ - 1 = 343 - 1 = **342**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00155', 'mba-entrance-bank', 'Logical Reasoning', 2, 10, 'Find the next term in the series: A1, C3, E5, G7, ?', 'The letters skip one position each time (A, C, E, G, ...), which corresponds to every alternate letter of the alphabet, so the next letter after G is **I**.

The numbers are the consecutive odd numbers (1, 3, 5, 7, ...), so the next number is **9**.

The next term is **I9**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00156', 'mba-entrance-bank', 'Logical Reasoning', 2, 11, 'Find the next number in the series: 5, 11, 23, 47, 95, ?', 'Each term follows the rule `(previous term × 2) + 1`: `5×2+1=11`, `11×2+1=23`, `23×2+1=47`, `47×2+1=95`.

Applying the same rule to 95 gives `95×2+1 = **191**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00157', 'mba-entrance-bank', 'Logical Reasoning', 2, 12, 'Find the number that does not belong with the others: 2, 3, 5, 7, 9, 11, 13.', 'All the numbers in this list except one are **prime numbers** (divisible only by 1 and themselves): 2, 3, 5, 7, 11, and 13 are all prime.

**9** is the odd one out, since `9 = 3 × 3` is a composite number, not prime.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00158', 'mba-entrance-bank', 'Logical Reasoning', 2, 13, 'Find the number that does not belong with the others: 8, 27, 64, 100, 125, 216.', 'Every number in this list except one is a **perfect cube**: `2³=8, 3³=27, 4³=64, 5³=125, 6³=216`.

**100** is the odd one out, since it is not the cube of any whole number (it is a perfect square, `10²`, not a perfect cube).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00159', 'mba-entrance-bank', 'Logical Reasoning', 2, 14, 'If in a certain code language COMPUTER is written as DPNQVUFS, how is MACHINE written in the same code?', 'Comparing COMPUTER and DPNQVUFS letter by letter shows each letter of the original word has been shifted **one place forward** in the alphabet: `C→D, O→P, M→N, P→Q, U→V, T→U, E→F, R→S`.

Applying the same forward shift of one place to MACHINE: `M→N, A→B, C→D, H→I, I→J, N→O, E→F`.

So MACHINE is coded as **NBDIJOF**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00160', 'mba-entrance-bank', 'Logical Reasoning', 2, 15, 'If in a certain code language APPLE is written as ZKKOV, how would MANGO be written in the same code?', 'The coding rule pairs each letter with its mirror position in the alphabet, where letter position `p` maps to position `27 - p` (so A↔Z, B↔Y, and so on): `A(1)→Z(26), P(16)→K(11), P(16)→K(11), L(12)→O(15), E(5)→V(22)`, matching APPLE→ZKKOV.

Applying the same rule to MANGO: `M(13)→N(14), A(1)→Z(26), N(14)→M(13), G(7)→T(20), O(15)→L(12)`.

So MANGO is coded as **NZMTL**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00161', 'mba-entrance-bank', 'Logical Reasoning', 2, 16, 'If in a certain code FRIEND is written as HTKGPF, how would CANDLE be written in the same code?', 'Comparing FRIEND and HTKGPF shows each letter has been shifted **two places forward** in the alphabet: `F(6)→H(8), R(18)→T(20), I(9)→K(11), E(5)→G(7), N(14)→P(16), D(4)→F(6)`.

Applying the same +2 shift to CANDLE: `C(3)→E(5), A(1)→C(3), N(14)→P(16), D(4)→F(6), L(12)→N(14), E(5)→G(7)`.

So CANDLE is coded as **ECPFNG**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00162', 'mba-entrance-bank', 'Logical Reasoning', 2, 17, 'In a certain code, TABLE is written as 20-1-2-12-5 (each letter replaced by its position in the alphabet). Using the same code, what is the code for CHAIR?', 'The coding rule simply replaces each letter with its **position in the alphabet** (T=20, A=1, B=2, L=12, E=5, confirming TABLE = 20-1-2-12-5).

Applying this to CHAIR: `C=3, H=8, A=1, I=9, R=18`.

So CHAIR is coded as **3-8-1-9-18**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00163', 'mba-entrance-bank', 'Logical Reasoning', 2, 18, 'In a code language, ROSE is written as URVH, and CHAIR is written as FKDLU. How would FRIEND be written in the same code?', 'Checking the pattern on ROSE: `R(18)→U(21), O(15)→R(18), S(19)→V(22), E(5)→H(8)` — each letter is shifted **three places forward**. CHAIR confirms this: `C→F, H→K, A→D, I→L, R→U`.

Applying the same +3 shift to FRIEND: `F(6)→I(9), R(18)→U(21), I(9)→L(12), E(5)→H(8), N(14)→Q(17), D(4)→G(7)`.

So FRIEND is coded as **IULHQG**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00164', 'mba-entrance-bank', 'Logical Reasoning', 2, 19, 'In a certain code language, ''sun rises in east'' is written as ''3 7 9 5'', ''moon rises at night'' is written as ''3 8 6 2'', and ''sun sets in west'' is written as ''9 4 5 1'', where ''rises'' is coded as ''3''. What is the code for ''east''?', 'Since ''rises'' = 3, the words ''sun'', ''in'' and ''east'' from the first sentence together correspond to the remaining codes `{7, 9, 5}`, in some order.

The third sentence, ''sun sets in west'' = `{9, 4, 5, 1}`, shares the words ''sun'' and ''in'' with the first sentence, so their codes must lie in the **intersection** of `{7, 9, 5}` and `{9, 4, 5, 1}`, which is `{9, 5}`.

That means ''sun'' and ''in'' take the codes 9 and 5 (in some order), leaving the one remaining code from the first sentence''s set, **7**, as the code for ''east''.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00165', 'mba-entrance-bank', 'Logical Reasoning', 2, 20, 'In a certain code, if BOOK is written as 2-15-15-11 (each letter replaced by its position in the alphabet), decode the number sequence 18-5-1-4 using the same logic.', 'Using the alphabet-position code (confirmed by BOOK: B=2, O=15, O=15, K=11), we reverse the process for each number: `18=R, 5=E, 1=A, 4=D`.

Decoding 18-5-1-4 gives the word **READ**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00166', 'mba-entrance-bank', 'Logical Reasoning', 2, 21, 'In a code language, FLOWER is written as EKNVDQ. What is the coding logic, and how would GARDEN be written in the same code?', 'Comparing FLOWER and EKNVDQ letter by letter shows each letter has been shifted **one place backward** in the alphabet: `F→E, L→K, O→N, W→V, E→D, R→Q`.

Applying the same backward shift to GARDEN: `G→F, A→Z (wrapping around), R→Q, D→C, E→D, N→M`.

So GARDEN is coded as **FZQCDM**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00167', 'mba-entrance-bank', 'Logical Reasoning', 2, 22, 'A man walks 5 km north, then turns right and walks 3 km, then turns right again and walks 5 km. How far is he from his starting point, and in which direction?', 'Starting at the origin facing north, walking 5 km north brings him to a point 5 km north of start.

Turning right (now facing east) and walking 3 km moves him 3 km east; turning right again (now facing south) and walking 5 km brings him back down by exactly the 5 km he had gone up.

His net displacement is therefore purely **3 km to the east** of the starting point, since the northward and southward legs cancel out exactly.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00168', 'mba-entrance-bank', 'Logical Reasoning', 2, 23, 'Ravi walks 10 m towards south, then turns left and walks 20 m, then turns left again and walks 10 m, then turns left again and walks 15 m. How far and in which direction is he from his starting point?', 'Starting at the origin facing south: walking 10 m south reaches `(0, -10)`. Turning left (south → east) and walking 20 m reaches `(20, -10)`.

Turning left again (east → north) and walking 10 m reaches `(20, 0)`. Turning left once more (north → west) and walking 15 m reaches `(5, 0)`.

His final position, `(5, 0)`, is **5 metres to the east** of the starting point.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00169', 'mba-entrance-bank', 'Logical Reasoning', 2, 24, 'Point A is 4 km north of point B. Point C is 3 km east of point A. Point D is 6 km south of point C. What is the distance and direction of D from B?', 'Taking B as the origin `(0,0)`: A, 4 km north of B, is at `(0, 4)`. C, 3 km east of A, is at `(3, 4)`. D, 6 km south of C, is at `(3, 4-6) = (3, -2)`.

The straight-line distance from D to B is `√(3² + 2²) = √13 ≈ 3.6 km`.

Since D lies 3 km east and 2 km south of B, D is located to the **south-east of B, at a distance of √13 ≈ 3.6 km**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00170', 'mba-entrance-bank', 'Logical Reasoning', 2, 25, 'A man starts from his house and walks 8 km towards east, then turns south and walks 6 km. Find the shortest distance between his starting point and his current position.', 'Taking the house as the origin, walking 8 km east reaches `(8, 0)`, and then 6 km south reaches `(8, -6)`.

The shortest (straight-line) distance from the origin is the hypotenuse of a right triangle with legs 8 and 6: `√(8² + 6²) = √(64+36) = √100`.

The shortest distance is **10 km**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00171', 'mba-entrance-bank', 'Logical Reasoning', 2, 26, 'Rahul is facing north. He turns 135° clockwise and then 180° anticlockwise. Which direction is he facing now?', 'Starting at north (treated as 0°, with clockwise bearings increasing), turning 135° clockwise brings him to `0° + 135° = 135°`, which corresponds to the **south-east** direction.

Turning 180° anticlockwise from there subtracts 180°: `135° - 180° = -45°`, which, taken modulo 360°, equals `315°` — the **north-west** direction.

Rahul now faces **north-west**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00172', 'mba-entrance-bank', 'Logical Reasoning', 2, 27, 'A person walks 6 km towards east, then turns 90° clockwise and walks 6 km, then turns 90° clockwise again and walks 3 km, then turns 90° clockwise again and walks 3 km. How far is the person from the starting point?', 'Starting at the origin facing east: walking 6 km east reaches `(6,0)`. Turning 90° clockwise (east→south) and walking 6 km reaches `(6,-6)`.

Turning 90° clockwise again (south→west) and walking 3 km reaches `(3,-6)`. Turning 90° clockwise once more (west→north) and walking 3 km reaches `(3,-3)`.

The distance from the origin is `√(3² + 3²) = √18 = 3√2 ≈ **4.24 km**`, in the south-east direction from the start.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00173', 'mba-entrance-bank', 'Logical Reasoning', 2, 28, 'Pointing to a photograph, a man says, ''He is the son of my grandfather''s only son, and I have no brothers.'' How is the man in the photograph related to the speaker?', 'The speaker''s **grandfather''s only son** must be the speaker''s own father (since the speaker belongs to that generation).

So the photograph shows ''the son of my father'' — which would normally mean the speaker''s brother. However, the speaker explicitly states **''I have no brothers''**, so the only remaining possibility is that the photograph is of **the speaker himself**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00174', 'mba-entrance-bank', 'Logical Reasoning', 2, 29, 'A is the brother of B. B is the sister of C. C is the father of D. How is D related to A?', 'Since A is B''s brother, A is male. B is C''s sister, which means B and C share the same parents, and so does A, meaning A and C are also siblings.

C is D''s father, so C is male and D is his child. Since A is C''s sibling (and male), A is D''s **paternal uncle**, meaning D is A''s **nephew or niece**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00175', 'mba-entrance-bank', 'Logical Reasoning', 2, 30, 'Introducing a man, a woman says, ''His mother is the only daughter of my mother.'' How is the woman related to the man?', 'The phrase **''the only daughter of my mother''** refers to the woman herself, since she is her own mother''s daughter (and the only one).

So ''his mother'' refers to the woman speaking. This means the man being introduced is the woman''s **son**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00176', 'mba-entrance-bank', 'Logical Reasoning', 2, 31, 'P is the son of Q. Q and R are siblings. R has a daughter S. How is S related to P?', 'Since Q and R are siblings, and P is Q''s son while S is R''s daughter, P and S are the children of two siblings.

This makes P and S **first cousins** of each other.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00177', 'mba-entrance-bank', 'Logical Reasoning', 2, 32, 'Looking at a man, Priya says, ''His father''s sister is my aunt.'' How is the man related to Priya?', 'The woman described — **the man''s father''s sister** — is his paternal aunt. Priya states that this same woman is **also her aunt**.

For one woman to be the aunt of both the man and Priya, one of Priya''s parents must be a sibling of that same woman — meaning the man''s father and Priya''s parent are themselves siblings. This makes the man and Priya **cousins**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00178', 'mba-entrance-bank', 'Logical Reasoning', 2, 33, 'A woman introduces a man as, ''He is the son of the only brother of my father.'' How is the man related to the woman?', 'The woman''s **father''s only brother** is her paternal uncle.

The son of that uncle is, by definition, the woman''s **(paternal) first cousin**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00179', 'mba-entrance-bank', 'Logical Reasoning', 2, 34, 'Pointing to a man, a woman says, ''His wife is the only daughter of my mother.'' How is the woman related to the man?', 'The phrase **''the only daughter of my mother''** refers to the woman herself.

So ''his wife'' refers to the woman speaking, which means the man is the woman''s **husband**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00180', 'mba-entrance-bank', 'Logical Reasoning', 2, 35, 'A is B''s sister. C is B''s mother. D is C''s father. How is A related to D?', 'Since C is B''s mother and A is B''s sister, A shares the same mother, C, as B.

D is C''s father, making D the **maternal grandfather** of both A and B — so A is D''s **granddaughter**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00181', 'mba-entrance-bank', 'Logical Reasoning', 2, 36, 'Statements: All roses are flowers. Some flowers are red. Conclusions: I. Some roses are red. II. Some red things are flowers. Which conclusion(s) logically follow?', 'Conclusion I does not necessarily follow: knowing that all roses are flowers and some flowers are red does not guarantee that the ''red'' subset of flowers overlaps specifically with the ''rose'' subset — the red flowers could all be a different kind entirely.

Conclusion II does follow: ''some flowers are red'' is a particular statement, and its **logical conversion** — ''some red things are flowers'' — is always valid, since the same overlapping elements that make flowers red also make red things flowers.

**Only conclusion II follows.**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00182', 'mba-entrance-bank', 'Logical Reasoning', 2, 37, 'Statements: All cats are animals. No animal is a plant. Conclusions: I. No cat is a plant. II. Some animals are cats. Which conclusion(s) logically follow?', 'Since all cats are animals, and no animal is a plant, it follows that no cat can be a plant either — **conclusion I is valid** (a standard valid syllogism chain).

Since all cats are animals, and the set of cats is assumed non-empty, it also follows by logical conversion that some animals must be cats — **conclusion II is valid** as well.

**Both conclusions I and II follow.**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00183', 'mba-entrance-bank', 'Logical Reasoning', 2, 38, 'Statements: Some teachers are writers. All writers are readers. Conclusions: I. Some teachers are readers. II. All readers are writers. Which conclusion(s) logically follow?', 'Since some teachers are writers, and all writers are readers, the teachers who are writers must also be readers — so **conclusion I follows** (a valid ''some-all-some'' syllogism).

Conclusion II reverses the direction of a universal statement (''all writers are readers'' does not imply ''all readers are writers'') — this is a logical fallacy, so **conclusion II does not follow**.

**Only conclusion I follows.**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00184', 'mba-entrance-bank', 'Logical Reasoning', 2, 39, 'Statements: No doctor is a fool. All fools are stubborn. Conclusions: I. No doctor is stubborn. II. Some stubborn people are not doctors. Which conclusion(s) logically follow?', 'Conclusion I does not follow: doctors and fools are disjoint groups, but doctors could still overlap with stubborn people who are not fools, since ''stubborn'' is a broader category than ''fools''.

Conclusion II does follow: since all fools are stubborn, and no doctor is a fool, the fools (who are stubborn) must lie entirely outside the doctor group — meaning there exist stubborn people (the fools) who are not doctors.

**Only conclusion II follows.**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00185', 'mba-entrance-bank', 'Logical Reasoning', 2, 40, 'Statements: All pens are pencils. All pencils are erasers. Conclusions: I. All pens are erasers. II. Some erasers are pens. Which conclusion(s) logically follow?', 'Since all pens are pencils, and all pencils are erasers, it follows directly by transitivity that all pens are erasers — **conclusion I follows** (a classic valid ''Barbara'' syllogism).

Since all pens are erasers (from conclusion I) and pens form a non-empty group, logical conversion gives that some erasers must be pens — **conclusion II also follows**.

**Both conclusions I and II follow.**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00186', 'mba-entrance-bank', 'Logical Reasoning', 2, 41, 'Statements: Some books are novels. No novel is a magazine. Conclusions: I. Some books are not magazines. II. No book is a magazine. Which conclusion(s) logically follow?', 'Since some books are novels, and no novel is a magazine, those books that are novels cannot be magazines — so there definitely exist some books that are not magazines, meaning **conclusion I follows**.

Conclusion II is too strong: we only know that the novel-books are not magazines; other books outside that overlap could still be magazines, so **conclusion II does not follow**.

**Only conclusion I follows.**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00187', 'mba-entrance-bank', 'Logical Reasoning', 2, 42, 'Statements: All squares are rectangles. All rectangles are quadrilaterals. Conclusions: I. All squares are quadrilaterals. II. Some quadrilaterals are squares. Which conclusion(s) logically follow?', 'Since all squares are rectangles, and all rectangles are quadrilaterals, by transitivity all squares must be quadrilaterals — **conclusion I follows**.

Since squares form a non-empty group and all squares are quadrilaterals, logical conversion gives that some quadrilaterals must be squares — **conclusion II also follows**.

**Both conclusions I and II follow.**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00188', 'mba-entrance-bank', 'Logical Reasoning', 2, 43, 'Statements: Some actors are singers. Some singers are dancers. Conclusions: I. Some actors are dancers. II. Some dancers are actors. Which conclusion(s) logically follow?', 'Both premises are ''particular'' (some...are) statements, and the middle term ''singers'' is not guaranteed to refer to the **same** subset of singers in both statements.

The singers who are actors need not be the same singers who are dancers, so no valid connection between actors and dancers can be established — this is the classic **fallacy of the undistributed middle term**.

**Neither conclusion I nor II necessarily follows.**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00189', 'mba-entrance-bank', 'Logical Reasoning', 2, 44, 'In a class of 30 students, Raj ranks 12th from the top. There are 8 students between Raj and Meena, with Meena ranking below Raj. Find Meena''s rank from the bottom of the class.', 'Since 8 students sit between Raj (rank 12 from the top) and Meena, Meena''s rank from the top is `12 + 8 + 1 = 21`.

To convert a rank from the top into a rank from the bottom in a class of 30: `rank from bottom = 30 - rank from top + 1 = 30 - 21 + 1`.

Meena ranks **10th from the bottom**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00190', 'mba-entrance-bank', 'Logical Reasoning', 2, 45, 'The sum of the ages of a father and son is 60 years. Six years ago, the father''s age was five times the son''s age. Find their present ages.', 'Let the son''s present age be `S` and the father''s be `F`, with `F + S = 60`.

Six years ago, the father''s age was five times the son''s: `F - 6 = 5(S - 6)`, which simplifies to `F = 5S - 24`.

Substituting into the first equation: `(5S - 24) + S = 60`, giving `6S = 84`, so `S = 14` and `F = 46`.

The son is **14 years old** and the father is **46 years old**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00191', 'mba-entrance-bank', 'Logical Reasoning', 2, 46, 'A sum of Rs. 7800 is divided among A, B and C such that A gets twice as much as B, and B gets three times as much as C. Find C''s share.', 'Let C''s share be `x`. Then B''s share is `3x` (three times C''s), and A''s share is `2 × 3x = 6x` (twice B''s).

The total is `x + 3x + 6x = 10x = 7800`, so `x = 780`.

C''s share is **Rs. 780**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00192', 'mba-entrance-bank', 'Logical Reasoning', 2, 47, 'Among five friends, Aman is taller than Bala but shorter than Chetan. Divya is taller than Chetan. Esha is shorter than Bala. Who is the tallest and who is the shortest?', 'Combining the clues: `Aman > Bala`, `Chetan > Aman`, `Divya > Chetan`, and `Bala > Esha`.

Chaining these together gives the complete order: `Divya > Chetan > Aman > Bala > Esha`.

**Divya** is the tallest and **Esha** is the shortest.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00193', 'mba-entrance-bank', 'Logical Reasoning', 2, 48, 'A father is currently 4 times as old as his son. In 20 years, he will be twice as old as his son. Find their present ages.', 'Let the son''s present age be `x`, so the father''s present age is `4x`.

In 20 years: `4x + 20 = 2(x + 20)`, which simplifies to `4x + 20 = 2x + 40`, giving `2x = 20`, so `x = 10`.

The son is currently **10 years old** and the father is **40 years old**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00194', 'mba-entrance-bank', 'Logical Reasoning', 2, 49, 'A bag contains coins of three denominations — Rs. 1, Rs. 2 and Rs. 5 — in the ratio 5:3:2 by number of coins. If the total value of all coins is Rs. 420, find the number of Rs. 5 coins.', 'Let the number of coins be `5x, 3x, 2x` for the Rs. 1, Rs. 2 and Rs. 5 denominations respectively.

Their total value is `5x(1) + 3x(2) + 2x(5) = 5x + 6x + 10x = 21x`, and this equals `420`, so `x = 20`.

The number of Rs. 5 coins is `2x = **40**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00195', 'mba-entrance-bank', 'Logical Reasoning', 2, 50, 'Statement: ''The library will remain closed on Monday for maintenance.'' — notice posted by library authorities. Assumptions: I. Maintenance work can only be done when the library is closed. II. Visitors would want to know in advance about the closure. Which assumption(s) are implicit in the statement?', 'Assumption I is implicit: a notice announcing closure specifically **for maintenance** assumes that the maintenance work requires the facility to be shut, otherwise there would be no need to close it at all.

Assumption II is also implicit: the very act of **posting a notice in advance** assumes that informing visitors ahead of time is useful and expected.

**Both assumptions I and II are implicit.**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00196', 'mba-entrance-bank', 'Logical Reasoning', 2, 51, 'Statement: Several cases of food poisoning have been reported among students who ate at the college canteen. Courses of Action: I. The canteen should be temporarily closed and inspected for hygiene violations. II. All students in the college should be asked to stop eating any food permanently. Which course(s) of action logically follow?', 'Course I is a reasonable, **proportionate** response directly addressing the identified source of the problem (the canteen), so it follows.

Course II is an extreme and impractical overreaction — permanently stopping all food consumption is unrelated and disproportionate to the specific, localised problem described, so it does not follow.

**Only course of action I follows.**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00197', 'mba-entrance-bank', 'Logical Reasoning', 2, 52, 'Statement: ''Buy our premium subscription today and get the first month free.'' — advertisement. Assumptions: I. Some customers may be more willing to subscribe if given an initial trial period at no cost. II. All customers will definitely buy the subscription because of this offer. Which assumption(s) are implicit?', 'Assumption I is implicit: offering a free trial period as an incentive only makes sense if it is assumed that **some customers** are more likely to subscribe when given a no-cost trial.

Assumption II is not implicit, since it makes an unjustifiably absolute claim — advertisements do not assume **guaranteed universal success**, only a reasonable chance of increased uptake.

**Only assumption I is implicit.**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00198', 'mba-entrance-bank', 'Logical Reasoning', 2, 53, 'Statement: The government has made wearing helmets mandatory for all two-wheeler riders. Assumptions: I. Some riders may not wear helmets unless required by law. II. Helmets reduce the severity of injuries in accidents. Which assumption(s) are implicit?', 'Assumption I is implicit: mandating something by law only makes sense if it is assumed that **some people would not do it voluntarily**, requiring legal compulsion.

Assumption II is also implicit: the underlying rationale for requiring helmets at all assumes that **helmets genuinely reduce injury severity**, which is why the mandate is considered worthwhile.

**Both assumptions I and II are implicit.**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00199', 'mba-entrance-bank', 'Logical Reasoning', 2, 54, 'Statement: The annual rainfall in a region has declined by 40% over the last decade, severely affecting crop yields. Courses of Action: I. The government should promote drought-resistant crop varieties and improve irrigation infrastructure in the region. II. All farming activity in the region should be permanently banned. Which course(s) of action logically follow?', 'Course I is a constructive, proportionate response that directly targets the identified cause (reduced rainfall affecting crops), so it follows.

Course II is an extreme overreaction that ignores feasible, less drastic alternatives (such as those in Course I), so it does not follow.

**Only course of action I follows.**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00200', 'mba-entrance-bank', 'Logical Reasoning', 2, 55, 'Statement: ''Please switch off the lights when leaving the room.'' — notice in an office. Assumptions: I. Some employees may leave lights on unnecessarily if not reminded. II. Switching off lights when not in use helps save electricity. Which assumption(s) are implicit?', 'Assumption I is implicit: posting a reminder notice only makes sense if it is assumed that **some employees might otherwise forget** or neglect to switch off the lights.

Assumption II is also implicit, as it reflects the underlying rationale for the instruction — that turning off unused lights **conserves electricity**, which is presumably why the notice was put up in the first place.

**Both assumptions I and II are implicit.**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00201', 'mba-entrance-bank', 'Logical Reasoning', 2, 56, 'Find the angle between the hour hand and minute hand of a clock at 3:40.', 'The minute hand moves `6°` per minute, so at 40 minutes it is at `40 × 6° = 240°`.

The hour hand moves `30°` per hour plus `0.5°` per minute; at 3:40 it is at `(3 × 30°) + (40 × 0.5°) = 90° + 20° = 110°`.

The angle between them is `|240° - 110°| = **130°**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00202', 'mba-entrance-bank', 'Logical Reasoning', 2, 57, 'At what time between 4 and 5 o''clock will the hour and minute hands of a clock coincide?', 'At 4:00, the hour hand is at `4 × 30° = 120°` while the minute hand is at `0°`, a gap of `120°`.

The minute hand gains on the hour hand at a relative rate of `6° - 0.5° = 5.5°` per minute, so closing a `120°` gap takes `120 ÷ 5.5 = 240/11 minutes ≈ 21 9/11 minutes`.

The hands coincide at **4:21 and 9/11 minutes** (approximately 4:21:49).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00203', 'mba-entrance-bank', 'Logical Reasoning', 2, 58, 'A clock is set right at 12 noon. The clock gains 10 minutes every 24 hours. What will be the approximate true time when this faulty clock indicates 1 PM the next day?', 'The faulty clock runs fast, showing `24h 10m = 1450` clock-minutes for every `1440` true minutes — a ratio of `1450 : 1440`, or `145:144`.

From 12 noon to 1 PM the next day is `25 hours = 1500` minutes of **clock time**. The corresponding true time is `1500 × (144/145) ≈ 1489.66` minutes, which is about `24 hours 49.7 minutes`.

So the true time is approximately **12:49:40 PM the next day** (about 24 hours, 49 minutes, 40 seconds after 12 noon).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00204', 'mba-entrance-bank', 'Logical Reasoning', 2, 59, 'How many times do the hour and minute hands of a clock overlap in a full 24-hour period?', 'In any 12-hour period, the hour and minute hands overlap exactly **11 times**, not 12 — because the minute hand, moving faster, only manages to ''lap'' the hour hand 11 times in that span (the apparent 12th overlap at the start and end of the 12-hour cycle is actually the same event).

Over a full 24-hour period, this doubles to `11 × 2 = **22 times**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00205', 'mba-entrance-bank', 'Logical Reasoning', 2, 60, 'January 1, 2023 was a Sunday. What day of the week was January 1, 2024?', 'The year 2023 is not a leap year (it is not divisible by 4), so it has exactly `365` days.

Since `365 = 52 × 7 + 1`, the calendar advances by exactly **one day** of the week over this span.

So January 1, 2024 fell on **Monday**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00206', 'mba-entrance-bank', 'Logical Reasoning', 2, 61, 'If today is Wednesday, what day of the week will it be after 100 days?', 'Since the days of the week repeat every 7 days, we only need the remainder of `100 ÷ 7`.

`100 = 14 × 7 + 2`, so the remainder is `2`, meaning the day of the week advances by 2 places from Wednesday.

Counting forward two days from Wednesday (Thursday, then Friday) gives **Friday**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00207', 'mba-entrance-bank', 'Logical Reasoning', 2, 62, 'A cube is painted red on all its faces and then cut into 27 smaller, equal cubes (a 3×3×3 arrangement). How many of the smaller cubes have exactly two faces painted red?', 'In an `n×n×n` cube cut into unit cubes, the small cubes with **exactly two painted faces** are those lying along an edge but not at a corner. There are 12 edges on a cube, and each edge contributes `(n-2)` such cubes.

Here `n = 3`, so each edge contributes `3 - 2 = 1` such cube, giving `12 × 1 = **12 cubes**` with exactly two faces painted.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00208', 'mba-entrance-bank', 'Logical Reasoning', 2, 63, 'A cube of side 4 cm is painted on all its faces and then cut into unit (1 cm) cubes. How many of the resulting small cubes have no face painted at all?', 'The small cubes with **no face painted** are precisely those lying entirely in the interior, not touching any outer surface. For an `n×n×n` cube, this count is `(n-2)³`.

Here `n = 4`, so the count is `(4-2)³ = 2³ = **8 cubes**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00209', 'mba-entrance-bank', 'Logical Reasoning', 2, 64, 'A cuboid of dimensions 4 cm × 3 cm × 2 cm is painted on all its outer surfaces and cut into 1 cm unit cubes. How many of the resulting cubes have exactly one face painted?', 'Since one dimension (2 cm) has no interior layer, every unit cube is on the outer surface in that direction — meaning each cube already has one painted face from either the top or bottom layer.

A cube keeps **exactly one** painted face only if it is also in the ''interior'' along the other two dimensions (4 cm and 3 cm), i.e., not on the boundary edge of those directions: that interior count per layer is `(4-2) × (3-2) = 2 × 1 = 2`.

With two such layers (top and bottom), the total is `2 × 2 = **4 cubes**` with exactly one face painted.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00210', 'mba-entrance-bank', 'Logical Reasoning', 2, 65, 'In a survey of 100 people, 60 like tea, 50 like coffee, and 30 like both tea and coffee. How many people like neither tea nor coffee?', 'Using the inclusion-exclusion principle, the number of people who like **at least one** of tea or coffee is `60 + 50 - 30 = 80`.

The number who like **neither** is therefore `100 - 80 = **20 people**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00211', 'mba-entrance-bank', 'Logical Reasoning', 2, 66, 'In a class of 50 students, 28 play cricket, 20 play football, and 10 play both sports. How many students play only cricket (and not football)?', 'The number of students who play **only cricket** is the total cricket players minus those who also play football.

`Only cricket = 28 - 10 = **18 students**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00212', 'mba-entrance-bank', 'Logical Reasoning', 2, 67, 'In a group of 120 people, 65 read newspaper A, 45 read newspaper B, and 25 read both A and B. How many people read exactly one of the two newspapers?', 'The number of people reading **only A** (not B) is `65 - 25 = 40`, and the number reading **only B** (not A) is `45 - 25 = 20`.

The number reading exactly one newspaper is the sum of these two exclusive groups: `40 + 20 = **60 people**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00213', 'mba-entrance-bank', 'Logical Reasoning', 2, 68, 'Find the missing number in the series: 4, 9, 20, 43, 90, ?', 'Each term follows the rule `(previous term × 2) + k`, where `k` increases by 1 each time: `4×2+1=9`, `9×2+2=20`, `20×2+3=43`, `43×2+4=90`.

Continuing the pattern, the next increment is 5, so the next term is `90×2+5 = 180+5 = **185**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00214', 'mba-entrance-bank', 'Logical Reasoning', 2, 69, 'If in a certain code PAPER is written as QBQFS (each letter shifted one place forward in the alphabet), how would PENCIL be written in the same code?', 'The rule, confirmed by PAPER→QBQFS (`P→Q, A→B, P→Q, E→F, R→S`), is that every letter is shifted **one place forward** in the alphabet.

Applying this to PENCIL: `P→Q, E→F, N→O, C→D, I→J, L→M`.

So PENCIL is coded as **QFODJM**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00215', 'mba-entrance-bank', 'Logical Reasoning', 2, 70, 'Pointing to a girl, Ramesh said, ''She is the daughter of my mother''s only brother.'' How is the girl related to Ramesh?', 'Ramesh''s **mother''s only brother** is his maternal uncle.

The daughter of that uncle is, by definition, Ramesh''s **(maternal) first cousin**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00216', 'mba-entrance-bank', 'Logical Reasoning', 2, 71, 'At what time between 7 and 8 o''clock will the hour and minute hands of a clock point in exactly opposite directions (180° apart)?', 'At 7:00, the hour hand is at `7 × 30° = 210°` and the minute hand is at `0°`.

Let `t` be the minutes past 7:00. The hour hand''s position is `210 + 0.5t` and the minute hand''s is `6t`; for the hands to be opposite, `(210 + 0.5t) - 6t = 180`, giving `5.5t = 30`, so `t = 30/5.5 = 60/11 = 5 5/11`.

The hands are opposite at **7:05 and 5/11 minutes** (approximately 7:05:27).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00217', 'mba-entrance-bank', 'Data Interpretation', 3, 0, 'The table below shows the quarterly revenue (Rs. lakh) of four products of a company:
P1: Q1=120, Q2=150, Q3=180, Q4=200
P2: Q1=100, Q2=110, Q3=130, Q4=140
P3: Q1=80, Q2=90, Q3=100, Q4=120
P4: Q1=60, Q2=70, Q3=90, Q4=110

What is the total revenue generated by all four products in Q3?', 'Adding the Q3 figures for all four products: `180 + 130 + 100 + 90`.

The total revenue in Q3 is **Rs. 500 lakh**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00218', 'mba-entrance-bank', 'Data Interpretation', 3, 1, 'The table below shows the quarterly revenue (Rs. lakh) of four products of a company:
P1: Q1=120, Q2=150, Q3=180, Q4=200
P2: Q1=100, Q2=110, Q3=130, Q4=140
P3: Q1=80, Q2=90, Q3=100, Q4=120
P4: Q1=60, Q2=70, Q3=90, Q4=110

What is the percentage increase in P1''s revenue from Q1 to Q4?', 'P1''s revenue rose from `120` in Q1 to `200` in Q4, an increase of `200 - 120 = 80`.

Percentage increase = `(80/120) × 100 = **66.67%**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00219', 'mba-entrance-bank', 'Data Interpretation', 3, 2, 'The table below shows the quarterly revenue (Rs. lakh) of four products of a company:
P1: Q1=120, Q2=150, Q3=180, Q4=200
P2: Q1=100, Q2=110, Q3=130, Q4=140
P3: Q1=80, Q2=90, Q3=100, Q4=120
P4: Q1=60, Q2=70, Q3=90, Q4=110

Which product showed the highest percentage growth in revenue from Q1 to Q4?', 'Computing the percentage growth for each product: P1 `= (200-120)/120 × 100 = 66.67%`; P2 `= (140-100)/100 × 100 = 40%`; P3 `= (120-80)/80 × 100 = 50%`; P4 `= (110-60)/60 × 100 = 83.33%`.

**P4** shows the highest percentage growth, at **83.33%**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00220', 'mba-entrance-bank', 'Data Interpretation', 3, 3, 'The table below shows the quarterly revenue (Rs. lakh) of four products of a company:
P1: Q1=120, Q2=150, Q3=180, Q4=200
P2: Q1=100, Q2=110, Q3=130, Q4=140
P3: Q1=80, Q2=90, Q3=100, Q4=120
P4: Q1=60, Q2=70, Q3=90, Q4=110

What is the ratio of P2''s total revenue (summed across all four quarters) to P3''s total revenue?', 'P2''s total across all quarters = `100 + 110 + 130 + 140 = 480`. P3''s total = `80 + 90 + 100 + 120 = 390`.

The ratio is `480 : 390`, which simplifies (dividing both by 30) to **16 : 13**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00221', 'mba-entrance-bank', 'Data Interpretation', 3, 4, 'The table below shows the quarterly revenue (Rs. lakh) of four products of a company:
P1: Q1=120, Q2=150, Q3=180, Q4=200
P2: Q1=100, Q2=110, Q3=130, Q4=140
P3: Q1=80, Q2=90, Q3=100, Q4=120
P4: Q1=60, Q2=70, Q3=90, Q4=110

By what percentage did the combined revenue of all four products increase from Q1 to Q4?', 'Combined Q1 revenue = `120+100+80+60 = 360`. Combined Q4 revenue = `200+140+120+110 = 570`.

Percentage increase = `(570-360)/360 × 100 = (210/360) × 100 = **58.33%**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00222', 'mba-entrance-bank', 'Data Interpretation', 3, 5, 'The table below shows the quarterly revenue (Rs. lakh) of four products of a company:
P1: Q1=120, Q2=150, Q3=180, Q4=200
P2: Q1=100, Q2=110, Q3=130, Q4=140
P3: Q1=80, Q2=90, Q3=100, Q4=120
P4: Q1=60, Q2=70, Q3=90, Q4=110

What is the average quarterly revenue of P1 over the four quarters?', 'Summing P1''s quarterly figures: `120+150+180+200 = 650`.

Average = `650 / 4 = **Rs. 162.5 lakh**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00223', 'mba-entrance-bank', 'Data Interpretation', 3, 6, 'A company''s annual expenses (total Rs. 36,00,000) are distributed across categories in a pie chart as follows: Salaries = 126°, Raw Materials = 90°, Rent = 54°, Marketing = 36°, Utilities = 27°, Miscellaneous = 27° (total 360°). What amount is spent on Salaries?', 'The Salaries sector''s share of the total = `126°/360° × 100 = 35%`.

Amount spent on Salaries = `35% of Rs. 36,00,000 = **Rs. 12,60,000**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00224', 'mba-entrance-bank', 'Data Interpretation', 3, 7, 'Using the pie chart of annual expenses (total Rs. 36,00,000; Salaries=126°, Raw Materials=90°, Rent=54°, Marketing=36°, Utilities=27°, Miscellaneous=27°), what is the combined amount spent on Rent and Marketing?', 'Rent''s share = `54°/360° × 100 = 15%`, giving `15% of 36,00,000 = Rs. 5,40,000`.

Marketing''s share = `36°/360° × 100 = 10%`, giving `10% of 36,00,000 = Rs. 3,60,000`.

Combined amount = `5,40,000 + 3,60,000 = **Rs. 9,00,000**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00225', 'mba-entrance-bank', 'Data Interpretation', 3, 8, 'Using the pie chart of annual expenses (total Rs. 36,00,000; Salaries=126°, Raw Materials=90°, Rent=54°, Marketing=36°, Utilities=27°, Miscellaneous=27°), what is the ratio of the amount spent on Raw Materials to the amount spent on Utilities?', 'Raw Materials'' share = `90°/360° × 100 = 25%`, giving an amount of `25% of 36,00,000 = Rs. 9,00,000`.

Utilities'' share = `27°/360° × 100 = 7.5%`, giving `Rs. 2,70,000`.

The ratio `9,00,000 : 2,70,000` simplifies (dividing by 90,000) to **10 : 3**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00226', 'mba-entrance-bank', 'Data Interpretation', 3, 9, 'Using the pie chart of annual expenses (total Rs. 36,00,000; Salaries=126°, Raw Materials=90°, Rent=54°, Marketing=36°, Utilities=27°, Miscellaneous=27°), if total expenses increase by 20% next year while the percentage distribution stays the same, what will be the new amount spent on Marketing?', 'The new total expenses = `36,00,000 × 1.20 = Rs. 43,20,000`.

Marketing''s share remains `36°/360° = 10%` of the total, so the new Marketing spend = `10% of 43,20,000 = **Rs. 4,32,000**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00227', 'mba-entrance-bank', 'Data Interpretation', 3, 10, 'Using the pie chart of annual expenses (total Rs. 36,00,000; Salaries=126°, Raw Materials=90°, Rent=54°, Marketing=36°, Utilities=27°, Miscellaneous=27°), what percentage of total expenses is represented by the combined share of Utilities and Miscellaneous?', 'The combined angle for Utilities and Miscellaneous is `27° + 27° = 54°`.

As a percentage of the full circle: `54°/360° × 100 = **15%**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00228', 'mba-entrance-bank', 'Data Interpretation', 3, 11, 'The following bar graph data shows the exports (in $ million) of five countries in 2021 and 2022:
