Overall growth = `(1050-950)/950 × 100 = (100/950) × 100 ≈ **10.53%**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00232', 'mba-entrance-bank', 'Data Interpretation', 3, 15, 'The following bar graph data shows the exports (in $ million) of five countries in 2021 and 2022:
