INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00233', 'mba-entrance-bank', 'Data Interpretation', 3, 16, 'The following bar graph data shows the exports (in $ million) of five countries in 2021 and 2022:
