INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00234', 'mba-entrance-bank', 'Data Interpretation', 3, 17, 'The table below shows the revenue and cost (Rs. crore) of five companies:
