INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00240', 'mba-entrance-bank', 'Data Interpretation', 3, 23, 'The table below shows the number of students who appeared for an exam and their pass percentage across five schools:
