INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00245', 'mba-entrance-bank', 'Data Interpretation', 3, 28, 'The following line graph shows a company''s monthly stock price (Rs. per share) over 6 months: Jan=200, Feb=220, Mar=210, Apr=250, May=230, Jun=260. What is the percentage change in stock price from January to June?', 'The stock price rose from `200` in January to `260` in June, an increase of `60`.

