INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00246', 'mba-entrance-bank', 'Data Interpretation', 3, 29, 'The following line graph shows a company''s monthly stock price (Rs. per share) over 6 months: Jan=200, Feb=220, Mar=210, Apr=250, May=230, Jun=260. In which month did the stock price register the highest month-on-month percentage increase?', 'Computing month-on-month percentage change: Feb `=(220-200)/200=10%`; Mar `=(210-220)/220≈-4.55%`; Apr `=(250-210)/210≈19.05%`; May `=(230-250)/250=-8%`; Jun `=(260-230)/230≈13.04%`.

