INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00247', 'mba-entrance-bank', 'Data Interpretation', 3, 30, 'The following line graph shows a company''s monthly stock price (Rs. per share) over 6 months: Jan=200, Feb=220, Mar=210, Apr=250, May=230, Jun=260. What is the average stock price over these 6 months?', 'Summing all six monthly prices: `200+220+210+250+230+260 = 1370`.

