INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00248', 'mba-entrance-bank', 'Data Interpretation', 3, 31, 'The following line graph shows a company''s monthly stock price (Rs. per share) over 6 months: Jan=200, Feb=220, Mar=210, Apr=250, May=230, Jun=260. Between which two consecutive months was the percentage decline the steepest?', 'The only two month-on-month declines are March-over-February `(210-220)/220 ≈ -4.55%` and May-over-April `(230-250)/250 = -8%`.

