INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00249', 'mba-entrance-bank', 'Data Interpretation', 3, 32, 'The following line graph shows a company''s monthly stock price (Rs. per share) over 6 months: Jan=200, Feb=220, Mar=210, Apr=250, May=230, Jun=260. If an investor bought 100 shares in January and sold all of them in June, what would be the total profit?', 'The profit per share is `260 - 200 = 60`.

