INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00250', 'mba-entrance-bank', 'Data Interpretation', 3, 33, 'The table below shows the total number of employees and the male-to-female ratio in five companies:
