INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00260', 'mba-entrance-bank', 'Data Interpretation', 3, 43, 'The table below shows the production of cars (in thousands) by four companies over three years:
