INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00263', 'mba-entrance-bank', 'Data Interpretation', 3, 46, 'Five banks lend the following amounts at simple interest:
