INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00266', 'mba-entrance-bank', 'Data Interpretation', 3, 49, 'Five students scored the following marks (out of 100) in four subjects:
