INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00272', 'mba-entrance-bank', 'Data Interpretation', 3, 55, 'A smartphone market of 50 million units is divided among five brands by market share: BrandA=30%, BrandB=25%, BrandC=20%, BrandD=15%, BrandE=10%. How many units did BrandB sell?', 'BrandB''s share is `25%` of the `50 million` unit market.

Units sold = `25% of 50 million = **12.5 million units**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00273', 'mba-entrance-bank', 'Data Interpretation', 3, 56, 'A smartphone market of 50 million units is divided among five brands by market share: BrandA=30%, BrandB=25%, BrandC=20%, BrandD=15%, BrandE=10%. What is the ratio of units sold by BrandA to units sold by BrandD?', 'BrandA''s units = `30% of 50 million = 15 million`. BrandD''s units = `15% of 50 million = 7.5 million`.

The ratio `15 : 7.5` simplifies to **2 : 1**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00274', 'mba-entrance-bank', 'Data Interpretation', 3, 57, 'A smartphone market of 50 million units is divided among five brands by market share: BrandA=30%, BrandB=25%, BrandC=20%, BrandD=15%, BrandE=10%. What is the combined market share of BrandC, BrandD and BrandE?', 'Adding their individual shares: `20% + 15% + 10%`.

The combined market share is **45%**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00275', 'mba-entrance-bank', 'Data Interpretation', 3, 58, 'A smartphone market of 50 million units is divided among five brands by market share: BrandA=30%, BrandB=25%, BrandC=20%, BrandD=15%, BrandE=10%. If the total market grows by 10% next year and BrandA''s share rises to 35%, how many units will BrandA sell next year?', 'The new total market size = `50 million × 1.10 = 55 million units`.

BrandA''s units next year = `35% of 55 million = **19.25 million units**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00276', 'mba-entrance-bank', 'Data Interpretation', 3, 59, 'A smartphone market of 50 million units is divided among five brands by market share: BrandA=30%, BrandB=25%, BrandC=20%, BrandD=15%, BrandE=10%. By how many million units does BrandA outsell BrandE?', 'BrandA''s units = `30% of 50 million = 15 million`. BrandE''s units = `10% of 50 million = 5 million`.

BrandA outsells BrandE by `15 - 5 = **10 million units**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00277', 'mba-entrance-bank', 'Data Interpretation', 3, 60, 'A household''s monthly budget of Rs. 60,000 is allocated as follows: Rent=30%, Food=20%, Transport=10%, Savings=25%, Miscellaneous=15%. How much is allocated to Savings?', 'Savings represent `25%` of the total monthly budget of `Rs. 60,000`.

Amount allocated to Savings = `25% of 60,000 = **Rs. 15,000**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00278', 'mba-entrance-bank', 'Data Interpretation', 3, 61, 'A household''s monthly budget of Rs. 60,000 is allocated as follows: Rent=30%, Food=20%, Transport=10%, Savings=25%, Miscellaneous=15%. What is the ratio of the Rent allocation to the Transport allocation?', 'Rent = `30% of 60,000 = Rs. 18,000`. Transport = `10% of 60,000 = Rs. 6,000`.

The ratio `18,000 : 6,000` simplifies to **3 : 1**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00279', 'mba-entrance-bank', 'Data Interpretation', 3, 62, 'A household''s monthly budget of Rs. 60,000 is allocated as follows: Rent=30%, Food=20%, Transport=10%, Savings=25%, Miscellaneous=15%. What is the combined amount allocated to Food and Miscellaneous?', 'Food = `20% of 60,000 = Rs. 12,000`. Miscellaneous = `15% of 60,000 = Rs. 9,000`.

Combined amount = `12,000 + 9,000 = **Rs. 21,000**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00280', 'mba-entrance-bank', 'Data Interpretation', 3, 63, 'A household''s monthly budget of Rs. 60,000 is allocated as follows: Rent=30%, Food=20%, Transport=10%, Savings=25%, Miscellaneous=15%. If the total budget rises to Rs. 72,000 next month with the same percentage distribution, how much will be allocated to Rent?', 'Rent''s share remains `30%` of the total budget.

New Rent allocation = `30% of 72,000 = **Rs. 21,600**`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00281', 'mba-entrance-bank', 'Data Interpretation', 3, 64, 'A household''s monthly budget of Rs. 60,000 is allocated as follows: Rent=30%, Food=20%, Transport=10%, Savings=25%, Miscellaneous=15%. What percentage of the budget is NOT allocated to Savings?', 'Since Savings account for `25%` of the budget, the remaining share not allocated to Savings is `100% - 25%`.

This remaining share is **75%**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('mba-q00282', 'mba-entrance-bank', 'Data Interpretation', 3, 65, 'The table below shows the population (in lakh) of four cities in 2010 and 2020:
